CREATE OR REPLACE FUNCTION public.admin_pwa_auth_rate(p_ip text, p_login text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item record; count_now integer; allowed boolean := true;
begin
  if coalesce(auth.role(),'') <> 'service_role' then raise insufficient_privilege; end if;
  if p_ip !~ '^[a-f0-9]{64}$' or p_login !~ '^[a-f0-9]{64}$' or p_ip is null or p_login is null then return false; end if;
  for item in select * from (values ('ip:'||p_ip,60,10),('login:'||p_login,900,100)) as v(key,seconds,max_attempts) order by key loop
    insert into public.admin_pwa_auth_limits(key,attempts,window_started_at)
    values(item.key,1,clock_timestamp())
    on conflict(key) do update set
      attempts=case when admin_pwa_auth_limits.window_started_at <= clock_timestamp()-make_interval(secs=>item.seconds) then 1 else least(admin_pwa_auth_limits.attempts+1,1000000) end,
      window_started_at=case when admin_pwa_auth_limits.window_started_at <= clock_timestamp()-make_interval(secs=>item.seconds) then clock_timestamp() else admin_pwa_auth_limits.window_started_at end
    returning attempts into count_now;
    if count_now > item.max_attempts then allowed := false; end if;
  end loop;
  delete from public.admin_pwa_auth_limits where window_started_at < clock_timestamp()-interval '1 day';
  return allowed;
end $function$

CREATE OR REPLACE FUNCTION public.admin_pwa_investment_commit(p_data jsonb, p_expected_version bigint, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_data jsonb; old_tx jsonb; next_tx jsonb; existing public.admin_pwa_investment_commits%rowtype;
  actor_role text; fund_balance numeric; old_operating numeric; next_operating numeric;
  cash_delta numeric := 0; bank_delta numeric := 0; method text; next_method text; amount numeric;
  holding jsonb; available_quantity numeric; trade_quantity numeric; old_quantity numeric; result jsonb;
begin
  select u.role into actor_role from public.users u where u.id = auth.uid() and u.status = 'active' and u.role in ('admin','user');
  if actor_role is null then raise exception 'Tài khoản quản lý không hoạt động hoặc không có quyền.' using errcode = '42501'; end if;
  if p_request_id is null or p_expected_version is null or p_expected_version < 0 or p_data is null
    or jsonb_typeof(p_data->'transactions') is distinct from 'array' then
    raise exception 'Dữ liệu hoặc phiên bản danh mục không hợp lệ.' using errcode = '22023';
  end if;
  -- Acquire the SAME global ledger lock used by invoices/cash/settings before
  -- the portfolio lock. Consistent order avoids cross-table deadlocks.
  perform pg_advisory_xact_lock(20261005,120000);
  perform pg_advisory_xact_lock(20261008,417800);
  select * into existing from public.admin_pwa_investment_commits where request_id = p_request_id;
  if found then
    if existing.actor_id <> auth.uid() or existing.expected_version <> p_expected_version
      or existing.data <> p_data then
      raise exception 'Mã lưu đã được dùng cho một thao tác khác.' using errcode = '22023';
    end if;
    return jsonb_build_object('version',existing.version,'data',existing.data);
  end if;
  old_data := public.admin_pwa_investment_read();
  if (old_data->>'version')::bigint <> p_expected_version then
    raise exception 'Danh mục đã thay đổi trên thiết bị khác. Hãy tải lại trước khi lưu.' using errcode = '40001';
  end if;
  old_data := old_data->'data';
  -- New transactions cannot invent opening funds or bypass the operating
  -- wallet by labeling themselves legacy. Explicit import is separate.
  for next_tx in select t from jsonb_array_elements(p_data->'transactions') t loop
    select t into old_tx from jsonb_array_elements(old_data->'transactions') t where t->>'id' = next_tx->>'id';
    if next_tx->>'fundingSource' is distinct from 'investment-wallet' then
      if old_tx is null or next_tx <> old_tx then
        raise exception 'Giao dịch cũ phải nhập từ bản sao Electron đã đối soát; không được tạo hoặc sửa như giao dịch mới.' using errcode = '22023';
      end if;
      continue;
    end if;
    if old_tx is not null and old_tx->>'fundingSource' is distinct from 'investment-wallet' then
      raise exception 'Không được đổi nguồn vốn giao dịch cũ.' using errcode = '22023';
    end if;
    method := next_tx->'walletPosting'->>'paymentMethod';
    if method is null or method not in ('cash','transfer') or jsonb_typeof(next_tx->'walletPosting'->'amount') is distinct from 'number'
      or jsonb_typeof(next_tx->'amountVnd') is distinct from 'number' then
      raise exception 'Giao dịch phải có số tiền và ví thanh toán hợp lệ.' using errcode = '22023';
    end if;
    amount := (next_tx->>'amountVnd')::numeric;
    if amount <= 0 or amount <> trunc(amount) or amount > 9007199254740991
      or (next_tx->'walletPosting'->>'amount')::numeric <> (case when next_tx->>'transactionType' in ('buy','withdraw') then -amount when next_tx->>'transactionType' in ('sell','deposit') then amount else null end)
      or next_tx->>'transactionType' not in ('buy','withdraw','sell','deposit') then
      raise exception 'Dấu hoặc số tiền giao dịch đầu tư không hợp lệ.' using errcode = '22023';
    end if;
    if next_tx is distinct from old_tx and next_tx->>'transactionType' in ('buy','sell') then
      if jsonb_typeof(next_tx->'quantity') is distinct from 'number' or (next_tx->>'quantity')::numeric <= 0 then
        raise exception 'Số lượng tài sản giao dịch phải lớn hơn 0.' using errcode = '22023';
      end if;
      trade_quantity := (next_tx->>'quantity')::numeric;
      if next_tx->>'transactionType' = 'sell' then
        select h into holding from jsonb_array_elements(old_data->'holdings') h where upper(h->>'symbol') = upper(next_tx->>'assetSymbol');
        if holding is null then raise exception 'Không có tài sản để bán/tất toán.' using errcode = '22023'; end if;
        if holding->>'category' = 'savings' then
          available_quantity := case when (holding->>'quantity')::jsonb->>'status' = 'settled' then 0 else 1 end;
        elsif split_part(holding->>'quantity',' ',1) ~ '^([0-9]+)(\.[0-9]+)?$' then
          available_quantity := split_part(holding->>'quantity',' ',1)::numeric;
        else raise exception 'Chưa xác định được số lượng tài sản để bán.' using errcode = '22023'; end if;
        if old_tx is not null and upper(old_tx->>'assetSymbol') = upper(next_tx->>'assetSymbol') then
          old_quantity := coalesce((old_tx->>'quantity')::numeric,0);
          available_quantity := available_quantity + case when old_tx->>'transactionType' = 'sell' then old_quantity when old_tx->>'transactionType' = 'buy' then -old_quantity else 0 end;
        end if;
        if trade_quantity > available_quantity then raise exception 'Số lượng bán vượt quá tài sản đang nắm giữ.' using errcode = '22023'; end if;
      end if;
    end if;
  end loop;
  select coalesce(sum((t->'walletPosting'->>'amount')::numeric),0) into fund_balance
    from jsonb_array_elements(p_data->'transactions') t where t->>'fundingSource' = 'investment-wallet';
  if fund_balance < 0 or fund_balance > 9007199254740991 then
    raise exception 'Ví đầu tư không đủ tiền hoặc số dư vượt giới hạn.' using errcode = '22023';
  end if;
  -- Compare each transaction against the locked cloud snapshot, deriving
  -- operating movements server-side. Client supplies no arbitrary receipts.
  for old_tx,next_tx in
    select o.t,n.t from jsonb_array_elements(old_data->'transactions') o(t)
    full join jsonb_array_elements(p_data->'transactions') n(t) on o.t->>'id' = n.t->>'id'
  loop
    if old_tx is not distinct from next_tx then continue; end if;
    old_operating := 0; next_operating := 0;
    method := old_tx->'walletPosting'->>'paymentMethod';
    next_method := next_tx->'walletPosting'->>'paymentMethod';
    if old_tx is not null and old_tx->>'fundingSource' is distinct from 'investment-wallet' then
      if actor_role <> 'admin' or next_tx is not null then
        raise exception 'Chỉ admin được hoàn tác giao dịch cũ thuộc Ví vận hành.' using errcode = '42501';
      end if;
      old_operating := coalesce((old_tx->'walletPosting'->>'amount')::numeric,0);
    elsif old_tx->>'transactionType' in ('deposit','withdraw') then
      old_operating := -(old_tx->'walletPosting'->>'amount')::numeric;
    end if;
    if next_tx->>'transactionType' in ('deposit','withdraw') then
      next_operating := -(next_tx->'walletPosting'->>'amount')::numeric;
    end if;
    if old_operating <> 0 then
      if method = 'cash' then cash_delta := cash_delta-old_operating;
      elsif method = 'transfer' then bank_delta := bank_delta-old_operating;
      else raise exception 'Không xác định ví của giao dịch cũ.' using errcode = '22023'; end if;
    end if;
    if next_operating <> 0 then
      if next_method = 'cash' then cash_delta := cash_delta+next_operating;
      elsif next_method = 'transfer' then bank_delta := bank_delta+next_operating;
      else raise exception 'Không xác định ví của giao dịch mới.' using errcode = '22023'; end if;
    end if;
  end loop;
  -- Preserve existing server wallet triggers/constraints and chosen wallet.
  -- Credits are inserted first, then debits, all within this transaction.
  for method,amount in select x.method,x.amount from (values('cash',cash_delta),('transfer',bank_delta)) x(method,amount) where x.amount <> 0 order by x.amount desc loop
    if amount <> trunc(amount) or abs(amount) > 9007199254740991 then raise exception 'Chứng từ nguồn vốn không hợp lệ.' using errcode = '22023'; end if;
    insert into public.cash_transactions(id,type,category,transaction_date,amount,payment_method,note,created_at,updated_at)
    values('pwa-investment-'||p_request_id::text||'-'||method,case when amount > 0 then 'income' else 'expense' end,'investment_transfer',now(),abs(amount),method,'[Đầu tư PWA] Chuyển/hoàn tác vốn · '||p_request_id::text,now(),now());
  end loop;
  -- Validation/version/history/update run last, so any rejection rolls back
  -- ALL new receipts automatically, including role/shape/version failures.
  result := public.admin_pwa_investment_write(p_data,p_expected_version,p_request_id);
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_pwa_investment_import(p_data jsonb, p_expected_version bigint, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare snapshot jsonb; previous public.admin_pwa_investment_commits%rowtype; fund_balance numeric;
begin
  if not exists(select 1 from public.users u where u.id=auth.uid() and u.status='active' and u.role='admin') then
    raise exception 'Chỉ admin được nhập danh mục Electron đã đối soát.' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(20261008,417800);
  select * into previous from public.admin_pwa_investment_commits where request_id=p_request_id;
  if found then return public.admin_pwa_investment_write(p_data,p_expected_version,p_request_id); end if;
  snapshot := public.admin_pwa_investment_read();
  if (snapshot->>'version')::bigint <> p_expected_version then raise exception 'Danh mục đã thay đổi. Tải lại trước khi nhập.' using errcode='40001'; end if;
  if jsonb_array_length(snapshot->'data'->'holdings') > 0 or jsonb_array_length(snapshot->'data'->'transactions') > 0 then
    raise exception 'Chỉ nhập vào danh mục cloud trống; không ghi đè dữ liệu đã có.' using errcode='22023';
  end if;
  if jsonb_typeof(p_data->'transactions') is distinct from 'array' then raise exception 'Tệp giao dịch không hợp lệ.' using errcode='22023'; end if;
  select coalesce(sum((t->'walletPosting'->>'amount')::numeric),0) into fund_balance
    from jsonb_array_elements(p_data->'transactions') t where t->>'fundingSource'='investment-wallet';
  if fund_balance < 0 then raise exception 'Ví đầu tư trong tệp đang âm. Đối soát trên Electron trước khi nhập.' using errcode='22023'; end if;
  return public.admin_pwa_investment_write(p_data,p_expected_version,p_request_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_pwa_investment_read()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare snapshot public.admin_pwa_investment_store%rowtype;
begin
  if not exists(select 1 from public.users u where u.id = auth.uid() and u.status = 'active' and u.role in ('admin','user')) then
    raise exception 'Tài khoản quản lý không hoạt động hoặc không có quyền.' using errcode = '42501';
  end if;
  select * into snapshot from public.admin_pwa_investment_store where id = 'property-portfolio';
  if not found then return jsonb_build_object('version',0,'data',jsonb_build_object('holdings','[]'::jsonb,'transactions','[]'::jsonb,'portfolioSnapshots','[]'::jsonb,'categoryTargets','{}'::jsonb)); end if;
  return jsonb_build_object('version',snapshot.version,'data',snapshot.data);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_pwa_investment_write(p_data jsonb, p_expected_version bigint, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare snapshot public.admin_pwa_investment_store%rowtype; previous public.admin_pwa_investment_commits%rowtype;
begin
  if not exists(select 1 from public.users u where u.id = auth.uid() and u.status = 'active' and u.role in ('admin','user')) then
    raise exception 'Tài khoản quản lý không hoạt động hoặc không có quyền.' using errcode = '42501';
  end if;
  if p_expected_version is null or p_expected_version < 0 or p_request_id is null or p_data is null
    or jsonb_typeof(p_data) <> 'object' or octet_length(p_data::text) > 8388608
    or jsonb_typeof(p_data->'holdings') is distinct from 'array'
    or jsonb_typeof(p_data->'transactions') is distinct from 'array'
    or jsonb_typeof(p_data->'portfolioSnapshots') is distinct from 'array'
    or jsonb_typeof(p_data->'categoryTargets') is distinct from 'object' then
    raise exception 'Dữ liệu danh mục hoặc phiên bản không hợp lệ.' using errcode = '22023';
  end if;
  if exists(select 1 from jsonb_object_keys(p_data) as keys(key) where key not in ('holdings','transactions','portfolioSnapshots','categoryTargets'))
    or jsonb_array_length(p_data->'holdings') > 10000 or jsonb_array_length(p_data->'transactions') > 100000 or jsonb_array_length(p_data->'portfolioSnapshots') > 20000 then
    raise exception 'Danh mục vượt giới hạn hoặc chứa trường không hỗ trợ.' using errcode = '22023';
  end if;
  if exists(select 1 from jsonb_array_elements(p_data->'holdings') h where jsonb_typeof(h) <> 'object' or nullif(btrim(h->>'symbol'),'') is null or (h->>'category') is null or h->>'category' not in ('cash','gold','stocks','bonds','savings') or jsonb_typeof(h->'valueVnd') is distinct from 'number' or (h->>'valueVnd')::numeric < 0)
    or exists(select 1 from jsonb_array_elements(p_data->'holdings') h group by upper(h->>'symbol') having count(*) > 1)
    or exists(select 1 from jsonb_array_elements(p_data->'transactions') t where jsonb_typeof(t) <> 'object' or nullif(t->>'id','') is null or t->>'transactionType' is null or t->>'transactionType' not in ('deposit','withdraw','buy','sell','import-existing') or jsonb_typeof(t->'amountVnd') is distinct from 'number' or (t->>'amountVnd')::numeric < 0 or nullif(t->>'date','') is null)
    or exists(select 1 from jsonb_array_elements(p_data->'transactions') t group by t->>'id' having count(*) > 1) then
    raise exception 'Tài sản hoặc giao dịch không hợp lệ/trùng mã.' using errcode = '22023';
  end if;
  -- Single property portfolio: preserve the Electron shared management scope.
  -- Lock covers first insert, version check, history and row update together.
  perform pg_advisory_xact_lock(20261008, 417800);
  select * into previous from public.admin_pwa_investment_commits where request_id = p_request_id;
  if found then
    if previous.actor_id <> auth.uid() or previous.expected_version <> p_expected_version or previous.data <> p_data then
      raise exception 'Mã lưu đã được dùng cho một thao tác khác.' using errcode = '22023';
    end if;
    return jsonb_build_object('version',previous.version,'data',previous.data);
  end if;
  select * into snapshot from public.admin_pwa_investment_store where id = 'property-portfolio' for update;
  if coalesce(snapshot.version,0) <> p_expected_version then
    raise exception 'Danh mục đã thay đổi trên thiết bị khác. Hãy tải lại trước khi lưu.' using errcode = '40001';
  end if;
  insert into public.admin_pwa_investment_store(id,version,data,updated_by) values('property-portfolio',p_expected_version+1,p_data,auth.uid())
  on conflict(id) do update set version = excluded.version, data = excluded.data, updated_by = excluded.updated_by, updated_at = now();
  insert into public.admin_pwa_investment_commits(request_id,actor_id,expected_version,version,data) values(p_request_id,auth.uid(),p_expected_version,p_expected_version+1,p_data);
  return jsonb_build_object('version',p_expected_version+1,'data',p_data);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_pwa_reconcile_verified_sepay(p_tx jsonb, p_invoice_id text, p_actor uuid, p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare amount bigint; tx_id text; ref text; tx_key text; account text; occurred timestamptz; content text; matches text[];
  claim public.admin_pwa_bank_claims%rowtype; observed public.sepay_server_transactions%rowtype;
  invoice public.invoices%rowtype; event_invoice text; answer jsonb; new_receipt_id text;
  saved_claims text; saved_sub text; ctr public.contracts%rowtype;
begin
  if coalesce(auth.role(),'') <> 'service_role' then raise exception 'Only verified server requests are allowed.' using errcode='42501'; end if;
  if not exists(select 1 from public.users u where u.id=p_actor and u.role='admin' and u.status='active') then raise exception 'Active admin required.' using errcode='42501'; end if;
  if p_mode is null or p_mode not in ('reconcile','bank-receipt') or p_tx is null or jsonb_typeof(p_tx) <> 'object'
    or jsonb_typeof(p_tx->'amount_in') is distinct from 'number' or nullif(p_tx->>'id','') is null
    or (p_tx->>'amount_in')::numeric <= 0 or (p_tx->>'amount_in')::numeric > 2147483647
    or (p_tx->>'amount_in')::numeric <> trunc((p_tx->>'amount_in')::numeric)
    or (p_mode='reconcile' and nullif(p_invoice_id,'') is null) or (p_mode='bank-receipt' and p_invoice_id is not null) then
    raise exception 'Invalid verified payment.' using errcode='22023';
  end if;
  tx_id:=btrim(p_tx->>'id');ref:=nullif(btrim(p_tx->>'reference_number'),'');amount:=(p_tx->>'amount_in')::bigint;
  content:=coalesce(p_tx->>'transaction_content','');tx_key:=regexp_replace(upper(coalesce(ref,tx_id)),'[^A-Z0-9]','','g');
  if tx_key='' or length(tx_id)>128 or length(ref)>128 or length(content)>4000 or nullif(p_tx->>'transaction_date','') is null then raise exception 'Invalid bank reference/date.' using errcode='22023';end if;
  occurred:=(p_tx->>'transaction_date')::timestamptz;
  if not isfinite(occurred) or occurred>now()+interval '5 minutes' then raise exception 'Invalid bank date.' using errcode='22023';end if;
  select upper(regexp_replace(s.account_no,'[^A-Z0-9]','','gi')) into account from public.app_settings s;
  if nullif(account,'') is null or not (
    upper(regexp_replace(coalesce(p_tx->>'account_number',''),'[^A-Z0-9]','','gi'))=account
    or upper(regexp_replace(coalesce(p_tx->>'sub_account',''),'[^A-Z0-9]','','gi'))=account
  ) then raise exception 'Wrong recipient bank account.' using errcode='22023';end if;
  -- Same lock/order as webhook, invoices, settings and wallet writes.
  perform pg_advisory_xact_lock(20261005,120000);
  perform pg_advisory_xact_lock(hashtext('server-sepay:'||tx_key));
  select * into claim from public.admin_pwa_bank_claims c where c.external_id=tx_id or c.transaction_key=tx_key;
  if found then
    if claim.mode<>p_mode or claim.invoice_id is distinct from p_invoice_id or claim.amount<>amount or claim.external_id<>tx_id then raise exception 'Transaction is already assigned elsewhere.' using errcode='22023';end if;
    if p_mode='reconcile' then select * into invoice from public.invoices where id=claim.invoice_id;return jsonb_build_object('invoice',to_jsonb(invoice),'duplicate',true);end if;
    return jsonb_build_object('receiptId',claim.receipt_id,'duplicate',true);
  end if;
  select k.invoice_id into event_invoice from public.payment_event_keys k where k.key in (lower(ref),lower(tx_id)) limit 1;
  if event_invoice is null then
    select i.id into event_invoice from public.invoices i cross join lateral jsonb_array_elements(coalesce(i.payment_records,'[]'::jsonb)) r
      where lower(btrim(r->>'external_ref')) in (lower(ref),lower(tx_id)) or lower(btrim(r->>'external_id')) in (lower(ref),lower(tx_id)) limit 1;
  end if;
  if event_invoice is not null then
    if p_mode='reconcile' and event_invoice=p_invoice_id then select * into invoice from public.invoices where id=event_invoice;return jsonb_build_object('invoice',to_jsonb(invoice),'duplicate',true);end if;
    raise exception 'Already credited to an invoice.' using errcode='22023';
  end if;
  select * into observed from public.sepay_server_transactions t where t.transaction_key=tx_key or t.external_id=tx_id;
  if found and (observed.amount<>amount or observed.external_id<>tx_id or observed.status='recorded') then raise exception 'Verified bank record conflicts or is already recorded.' using errcode='22023';end if;
  -- Do not double-post a legacy desktop unmatched-bank receipt.
  if exists(select 1 from public.cash_transactions c where c.payment_method='transfer' and c.note is not null and (
    (ref is not null and position('Ref: '||ref||')' in c.note)>0) or position('Ref: '||tx_id||')' in c.note)>0)) then raise exception 'Bank receipt already exists.' using errcode='22023';end if;
  select array_agg(i.id) into matches from public.invoices i join public.rooms r on r.id=i.room_id where i.payment_status not in ('cancelled','merged')
    and position('P'||coalesce(nullif(regexp_replace(r.name,'\D','','g'),''),nullif(left(regexp_replace(upper(r.name),'[^A-Z0-9]','','g'),6),''),'XX')||'T'||lpad(i.month::text,2,'0')||i.year||'C'||right(regexp_replace(upper(i.id),'[^A-Z0-9]','','g'),12) in regexp_replace(upper(content),'[^A-Z0-9]','','g'))>0;
  if p_mode='reconcile' then
    if coalesce(cardinality(matches),0)<>1 or matches[1]<>p_invoice_id then raise exception 'No unique matching invoice.' using errcode='22023';end if;
    select * into invoice from public.invoices where id=p_invoice_id for update;
    if invoice.total_amount<=0 or amount>invoice.total_amount-coalesce(invoice.paid_amount,0) or invoice.payment_status='paid' then raise exception 'Invalid remaining amount.' using errcode='22023';end if;
  elsif coalesce(cardinality(matches),0)>0 then raise exception 'Invoice transfer cannot be credited again as other bank income.' using errcode='22023';end if;
  insert into public.admin_pwa_bank_claims(external_id,transaction_key,actor_id,mode,invoice_id,amount) values(tx_id,tx_key,p_actor,p_mode,p_invoice_id,amount);
  -- Publish verified provenance inside the SAME transaction before payment
  -- append; failure of wallet/RPC/trigger rolls this and the reservation back.
  insert into public.sepay_server_transactions(transaction_key,external_id,reference_number,amount,content,occurred_at,invoice_id,status)
    values(tx_key,tx_id,ref,amount,content,occurred,p_invoice_id,'unmatched')
    on conflict(transaction_key) do update set invoice_id=excluded.invoice_id;
  saved_claims:=current_setting('request.jwt.claims',true);saved_sub:=current_setting('request.jwt.claim.sub',true);
  perform set_config('request.jwt.claim.sub',p_actor::text,true);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',p_actor,'role','service_role')::text,true);
  if p_mode='reconcile' then
    answer:=public.record_invoice_payment_atomic(p_invoice_id,amount::integer,'transfer',(occurred at time zone 'Asia/Ho_Chi_Minh')::date,'Đối soát SePay đã xác minh (Ref: '||coalesce(ref,tx_id)||')',ref,tx_id,'sepay');
    if not coalesce((answer->>'applied')::boolean,false) and not coalesce((answer->>'duplicate')::boolean,false) then raise exception 'Payment was not applied.' using errcode='22023';end if;
    if coalesce((answer->>'transitioned_to_paid')::boolean,false) and invoice.is_settlement then
      select * into ctr from public.contracts c where c.room_id=invoice.room_id and c.status='active' order by c.created_at desc limit 1 for update;
      if ctr.id is not null and (ctr.tenant_id is null or ctr.tenant_id=invoice.tenant_id) then
        update public.rooms set status='vacant',tenant_name=null,tenant_phone=null,move_in_date=null,expected_end_date=null,electric_old=invoice.electric_new,electric_new=invoice.electric_new,water_old=invoice.water_new,water_new=invoice.water_new,has_move_in_receipt=false where id=invoice.room_id and status='ending';
        if found then update public.contracts set status='terminated',end_date=coalesce(invoice.invoice_date,(occurred at time zone 'Asia/Ho_Chi_Minh')::date),end_note=coalesce(invoice.damage_note,invoice.adjustment_note),final_electric=invoice.electric_new,final_water=invoice.water_new where id=ctr.id;end if;
      end if;
    end if;
  else
    new_receipt_id:='pwa-sepay-'||replace(gen_random_uuid()::text,'-','');
    insert into public.cash_transactions(id,type,category,transaction_date,amount,payment_method,note,created_at,updated_at)
      values(new_receipt_id,'income','other_income',occurred,amount,'transfer','Tiền vào ngân hàng chưa ghép hóa đơn qua Sepay: '||content||' (Ref: '||coalesce(ref,tx_id)||')',now(),now());
    update public.admin_pwa_bank_claims set receipt_id=new_receipt_id where external_id=tx_id;
    answer:=jsonb_build_object('receiptId',new_receipt_id,'duplicate',false);
  end if;
  update public.sepay_server_transactions set status='recorded' where transaction_key=tx_key;
  perform set_config('request.jwt.claim.sub',coalesce(saved_sub,''),true);perform set_config('request.jwt.claims',coalesce(saved_claims,'{}'),true);
  return answer;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_server_emails(p_limit integer DEFAULT 20, p_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF email_notification_deliveries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare remaining integer; daily integer; today date:=(now() at time zone 'UTC')::date; n integer;
begin
 select daily_limit into daily from email_automation_settings where enabled for update;
 if not found then return; end if;
 insert into email_send_budget(day) values(today) on conflict do nothing;
 select greatest(0,daily-reservations) into remaining from email_send_budget where day=today for update;
 -- Provider idempotency lasts 24 hours. Uncertain sends older than 23h need human review.
 update email_notification_deliveries set status='failed',error_message='Cần kiểm tra lịch sử Resend trước khi gửi lại: đã hết thời hạn chống trùng.',next_attempt_at='infinity',lease_token=null,lease_until=null
 where server_queue and status in ('queued','sending','failed') and first_attempt_at<now()-interval '23 hours';
 return query with candidates as (
  select id from email_notification_deliveries
  where server_queue and (p_id is null or id=p_id) and attempts<5 and next_attempt_at<=now()
   and (status in ('queued','failed') or (status='sending' and lease_until<now()))
  order by created_at,id for update skip locked limit least(greatest(p_limit,1),25,remaining)
 ), claimed as (
  update email_notification_deliveries d set status='sending',attempts=attempts+1,
   first_attempt_at=coalesce(first_attempt_at,now()),last_attempt_at=now(),lease_token=gen_random_uuid(),lease_until=now()+interval '5 minutes',error_message=null
  where d.id in(select id from candidates) returning d.*
 ) select * from claimed;
 get diagnostics n=row_count;
 update email_send_budget set reservations=reservations+n where day=today;
end $function$

CREATE OR REPLACE FUNCTION public.claim_tenant_payment_emails()
 RETURNS SETOF tenant_payment_emails
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare daily int; remaining int; n int; today date:=(now() at time zone 'UTC')::date;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service only';end if;
 select daily_limit into daily from email_automation_settings where enabled for update;
 if not found then return;end if;
 insert into email_send_budget(day,reservations) values(today,0) on conflict do nothing;
 select greatest(0,daily-reservations) into remaining from email_send_budget where day=today for update;
 return query with picked as (select id from tenant_payment_emails where
  ((status in ('queued','failed') and next_attempt_at<=now()) or (status='sending' and lease_until<now())) and attempts<5
  order by created_at for update skip locked limit least(remaining,10))
 update tenant_payment_emails e set status='sending',attempts=attempts+1,lease=gen_random_uuid(),lease_until=now()+interval '5 minutes'
 from picked p where e.id=p.id returning e.*;
 get diagnostics n=row_count;update email_send_budget set reservations=reservations+n where day=today;
end $function$

CREATE OR REPLACE FUNCTION public.confirm_invoice_debt_atomic(p_invoice_id text, p_expected_total integer, p_expected_paid integer, p_expected_electric_new numeric, p_expected_water_new numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
  invoice_row public.invoices%rowtype;
  room_row public.rooms%rowtype;
  contract_tenant_id text;
begin
  if actor_id is null or not exists (
    select 1 from public.users u where u.id = actor_id and u.status = 'active'
  ) then
    raise exception 'Phiên đăng nhập không hợp lệ hoặc tài khoản đã bị vô hiệu hóa.'
      using errcode = '42501';
  end if;

  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then raise exception 'Không tìm thấy hóa đơn.'; end if;

  if invoice_row.debt_confirmed_at is not null then
    return jsonb_build_object('invoice', to_jsonb(invoice_row), 'applied', false);
  end if;

  if invoice_row.payment_status not in ('unpaid', 'partial')
     or coalesce(invoice_row.total_amount, 0) <= coalesce(invoice_row.paid_amount, 0)
     or invoice_row.is_settlement is true
     or (coalesce(invoice_row.billing_reason, '') not in ('first_month', 'monthly', 'room_cycle')
         and invoice_row.is_first_month is not true) then
    raise exception 'Chỉ được chốt nợ hóa đơn kỳ thuê còn tiền phải thu.';
  end if;

  if (invoice_row.year, invoice_row.month) >=
     (extract(year from (now() at time zone 'Asia/Bangkok'))::integer,
      extract(month from (now() at time zone 'Asia/Bangkok'))::integer) then
    raise exception 'Chỉ được chốt nợ khi đã sang tháng mới.';
  end if;

  if invoice_row.total_amount is distinct from p_expected_total
     or invoice_row.paid_amount is distinct from p_expected_paid
     or invoice_row.electric_new is distinct from p_expected_electric_new
     or invoice_row.water_new is distinct from p_expected_water_new then
    raise exception 'Hóa đơn vừa thay đổi. Vui lòng tải lại và kiểm tra trước khi chốt.';
  end if;

  select tenant_id into contract_tenant_id
  from public.contracts
  where room_id = invoice_row.room_id and status = 'active'
  order by created_at desc limit 1;
  if contract_tenant_id is distinct from invoice_row.tenant_id then
    raise exception 'Hóa đơn không thuộc hợp đồng đang hoạt động của phòng.';
  end if;

  if exists (
    select 1 from public.invoices later
    where later.room_id = invoice_row.room_id
      and later.tenant_id = invoice_row.tenant_id
      and later.id <> invoice_row.id
      and later.payment_status not in ('cancelled', 'merged')
      and (coalesce(later.billing_reason, '') in ('first_month', 'monthly', 'room_cycle')
           or later.is_first_month is true)
      and (later.year, later.month) > (invoice_row.year, invoice_row.month)
  ) then
    raise exception 'Đã có hóa đơn kỳ sau. Cần kiểm tra chuỗi chỉ số trước khi chốt.';
  end if;

  select * into room_row from public.rooms where id = invoice_row.room_id for update;
  if not found or room_row.status not in ('occupied', 'ending') then
    raise exception 'Phòng không còn ở trạng thái được chốt nợ.';
  end if;
  if room_row.electric_new is distinct from invoice_row.electric_old
     or room_row.water_new is distinct from invoice_row.water_old then
    raise exception 'Chỉ số phòng không khớp đầu kỳ hóa đơn. Cần đối chiếu trước khi chốt.';
  end if;

  perform set_config('app.invoice_debt_closing', 'on', true);
  update public.invoices
  set debt_confirmed_at = now(), debt_confirmed_by = actor_id
  where id = p_invoice_id
  returning * into invoice_row;

  update public.rooms
  set electric_old = invoice_row.electric_new,
      electric_new = invoice_row.electric_new,
      water_old = invoice_row.water_new,
      water_new = invoice_row.water_new
  where id = invoice_row.room_id;

  return jsonb_build_object('invoice', to_jsonb(invoice_row), 'applied', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.contract_account_claim(p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contract_confirmations; lease uuid:=gen_random_uuid();
begin
 select * into c from contract_confirmations where token_hash=p_hash for update;
 if c.id is null or c.status<>'confirmed' or c.expires_at<=now() or c.account_ready_at is not null then raise exception 'Link cấp tài khoản đã dùng hoặc hết hạn.'; end if;
 if c.account_locked_until>now() then raise exception 'Đang cấp tài khoản. Hãy chờ một phút rồi thử lại.'; end if;
 if not exists(select 1 from contracts where id=c.contract_id and status='active') then raise exception 'Hợp đồng không còn hiệu lực.'; end if;
 update contract_confirmations set account_lease=lease,account_locked_until=now()+interval '60 seconds' where id=c.id;
 if not exists(select 1 from auth.users where id=c.account_user_id) then
  perform webmobile_prepare_tenant_auth(c.account_user_id,c.snapshot#>>'{tenant,id}',c.recipient_email,c.created_by,c.id);
 end if;
 return jsonb_build_object('id',c.id,'lease',lease,'userId',c.account_user_id,'email',c.recipient_email,'name',c.snapshot#>>'{tenant,full_name}');
end $function$

CREATE OR REPLACE FUNCTION public.contract_account_finish(p_hash text, p_user uuid, p_lease uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contract_confirmations; tid text;
begin
  select * into c from contract_confirmations where token_hash=p_hash for update;
  if c.id is null or c.status<>'confirmed' or c.expires_at<=now() or c.account_ready_at is not null or c.account_user_id<>p_user or c.account_lease<>p_lease or c.account_locked_until<=now() then raise exception 'Phiên cấp tài khoản đã thay đổi.'; end if;
  tid:=c.snapshot#>>'{tenant,id}';
  if not exists(select 1 from contracts where id=c.contract_id and tenant_id=tid and status='active') then raise exception 'Hợp đồng không còn hiệu lực.'; end if;
  perform webmobile_enroll_tenant(p_user,tid,c.recipient_email,c.created_by);
  update tenant_web_accounts set status='active',activated_at=now() where tenant_id=tid;
  update contract_confirmations set account_ready_at=now(),account_lease=null,account_locked_until=null where id=c.id;
end $function$

CREATE OR REPLACE FUNCTION public.contract_amendment_start(p_contract text, p_actor uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts; r rooms; t tenants; z service_zones; d contract_drafts; s jsonb; f jsonb; settings jsonb;
begin
 perform pg_advisory_xact_lock(hashtext('contract-lifecycle'));
 if not exists(select 1 from users where id=p_actor and role='admin' and status='active') then raise exception 'Chỉ admin được sửa hợp đồng.'; end if;
 if length(btrim(coalesce(p_reason,''))) not between 5 and 1000 then raise exception 'Nhập lý do sửa (5–1000 ký tự).'; end if;
 select * into c from contracts where id=p_contract for update;
 if c.id is null or c.status<>'active' then raise exception 'Chỉ sửa hợp đồng đang hiệu lực.'; end if;
 select * into r from rooms where id=c.room_id;
 select * into t from tenants where id=c.tenant_id;
 if t.id is null or not t.is_active or coalesce(t.email,'') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Bổ sung email hợp lệ trong hồ sơ khách thuê trước khi sửa.'; end if;
 if c.transfer_history is not null then raise exception 'Hợp đồng có nghiệp vụ chuyển phòng. Xử lý chuyển phòng trước khi sửa.'; end if;
 select * into d from contract_drafts where parent_contract_id=c.id and status='draft';
 if d.id is not null then return to_jsonb(d); end if;
 select snapshot into s from contract_confirmations where contract_id=c.id and status='confirmed' order by confirmed_at desc limit 1;
 f:=contract_form_values(to_jsonb(c));
 if s is null then
  select * into z from service_zones where id=r.service_zone_id;
  select jsonb_build_object('property_name',property_name,'property_address',property_address,'property_owner_name',property_owner_name,
   'property_owner_phone',property_owner_phone,'property_owner_id_card',property_owner_id_card,'bank_id',bank_id,'account_no',account_no,'account_name',account_name) into settings from app_settings limit 1;
  s:=jsonb_build_object('version',1,'room',jsonb_build_object('id',r.id,'name',r.name,'area',r.area),
   'tenant',jsonb_build_object('id',c.tenant_id,'full_name',c.tenant_name,'phone',c.tenant_phone,'email',lower(btrim(t.email)),'identity_card',c.tenant_id_card,
    'id_card_issued_date',c.tenant_id_card_issued_date,'id_card_issued_place',c.tenant_id_card_issued_place,'address',c.tenant_address),
   'settings',coalesce(settings,'{}'::jsonb),'services',jsonb_build_object('electricPrice',coalesce((to_jsonb(r)->>'electric_price')::integer,z.electric_price,0),'waterPrice',coalesce((to_jsonb(r)->>'water_price')::integer,z.water_price,0),
    'internetPrice',coalesce((to_jsonb(r)->>'wifi_price')::integer,z.internet_price,0),'cleaningPrice',coalesce((to_jsonb(r)->>'garbage_price')::integer,z.cleaning_price,0)),
   'assets',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'quantity',a.quantity,'condition',case a.status when 'error' then 'Có lỗi' when 'repairing' then 'Đang sửa' when 'ok' then 'Bình thường' else 'Chưa ghi nhận' end) order by a.sort_order),'[]'::jsonb) from room_assets a where a.room_id=r.id and a.quantity>0));
 end if;
 s:=(s-'amendment')||jsonb_build_object('form',f);
 if lower(btrim(t.email)) is distinct from lower(btrim(s#>>'{tenant,email}')) then raise exception 'Email đã đổi so với hợp đồng đã xác nhận. Xử lý tài khoản trước khi sửa.'; end if;
 s:=jsonb_set(s,'{tenant,email}',to_jsonb(lower(btrim(t.email))));
 perform set_config('app.contract_revision_write','1',true);
 insert into contract_drafts(room_id,tenant_id,recipient_email,snapshot,parent_contract_id,base_contract,before_snapshot,created_by)
 values(c.room_id,c.tenant_id,lower(btrim(t.email)),s||jsonb_build_object('amendment',jsonb_build_object('contractId',c.id,'previousForm',f,'reason',btrim(p_reason))),c.id,contract_term_values(to_jsonb(c)),s,p_actor) returning * into d;
 insert into contract_lifecycle_events(contract_id,draft_id,event_type,actor,reason,before_snapshot) values(c.id,d.id,'amendment_created',p_actor,btrim(p_reason),s);
 return to_jsonb(d);
end $function$

CREATE OR REPLACE FUNCTION public.contract_cancel_internal(p_contract text, p_actor uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts; check_result jsonb; account_was_unlocked boolean;
begin
 perform pg_advisory_xact_lock(hashtext('contract-lifecycle'));
 if not exists(select 1 from users where id=p_actor and role='admin' and status='active') then raise exception 'Chỉ admin được hủy hợp đồng.'; end if;
 if length(btrim(coalesce(p_reason,''))) not between 5 and 1000 then raise exception 'Nhập lý do hủy (5–1000 ký tự).'; end if;
 -- Serialize financial writes too, including invoice inserts and payment updates.
 lock table invoices,move_in_receipts,cash_transactions in share row exclusive mode;
 select * into c from contracts where id=p_contract for update;
 if c.id is null then raise exception 'Không tìm thấy hợp đồng.'; end if;
 if c.status='cancelled' then return jsonb_build_object('cancelled',true,'contractId',c.id); end if;
 perform 1 from rooms where id=c.room_id for update;
 check_result:=contract_cancellation_check(c.id);
 if not (check_result->>'allowed')::boolean then raise exception '%',check_result->>'reason'; end if;
 select status<>'locked' into account_was_unlocked from tenant_web_accounts where tenant_id=c.tenant_id for update;
 perform set_config('app.contract_revision_write','1',true);
 update contract_drafts set status='cancelled',revision=revision+1 where parent_contract_id=c.id and status='draft';
 update contract_confirmations set status='revoked',account_lease=null,account_locked_until=null where
  (contract_id=c.id or draft_id in(select id from contract_drafts where parent_contract_id=c.id)) and status<>'revoked';
 update contracts set status='cancelled',cancelled_at=now(),cancelled_by=p_actor,cancellation_reason=btrim(p_reason) where id=c.id;
 if not exists(select 1 from contracts where room_id=c.room_id and status='active') then
  update rooms set status='vacant',tenant_name=null,tenant_phone=null,tenant_email=null,tenant_id_card=null,move_in_date=null,
   contract_expiration=null,expected_end_date=null,has_move_in_receipt=false where id=c.room_id;
 end if;
 insert into contract_lifecycle_events(contract_id,event_type,actor,reason,before_snapshot,cancelled_account_version)
  values(c.id,'cancelled',p_actor,btrim(p_reason),to_jsonb(c),case when account_was_unlocked then (select session_version from tenant_web_accounts where tenant_id=c.tenant_id and status='locked') else null end);
 return jsonb_build_object('cancelled',true,'contractId',c.id);
end $function$

CREATE OR REPLACE FUNCTION public.contract_cancel(p_contract text, p_actor uuid, p_reason text, p_kind text, p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts; retained contracts; target_label text; explanation text; result jsonb; email text;
begin
 perform pg_advisory_xact_lock(hashtext('contract-lifecycle'));
 if not exists(select 1 from users where id=p_actor and role='admin' and status='active') then raise exception 'Chỉ admin được hủy hợp đồng.'; end if;
 lock table invoices,move_in_receipts,cash_transactions,payment_events,asset_snapshots in share row exclusive mode;
 select * into c from contracts where id=p_contract for update;
 if c.id is null then raise exception 'Không tìm thấy hợp đồng.'; end if;
 if c.status='cancelled' then return jsonb_build_object('cancelled',true,'contractId',c.id); end if;
 perform 1 from rooms where id=c.room_id for update;
 result:=contract_cancellation_check(c.id);
 if not (result->>'allowed')::boolean then raise exception '%',result->>'reason'; end if;
 if p_kind='test_reset' then p_reason:='Đang kiểm thử hệ thống.'; end if;
 if length(btrim(coalesce(p_reason,''))) not between 5 and 1000 then raise exception 'Nhập lý do hủy (5–1000 ký tự).'; end if;
 if p_kind='test_reset' then
  if not exists(select 1 from contract_test_designations where contract_id=c.id and room_id=c.room_id and tenant_id=c.tenant_id) then raise exception 'Hợp đồng chưa được đánh dấu thử nghiệm ở backend.'; end if;
  target_label:=c.id; explanation:='Kết thúc hợp đồng thử nghiệm: ';
 elsif p_kind='wrong_email' then
   select lower(btrim(t.email)) into target_label from tenants t
    where t.id=c.tenant_id and t.id=p_reference and t.is_active
    and t.email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    and not tenant_system_email_conflict(t.email)
    and lower(btrim(t.email)) is distinct from (select lower(btrim(cc.recipient_email)) from contract_confirmations cc
      join contract_drafts d on d.id=cc.draft_id where cc.contract_id=c.id and cc.confirmed_at is not null and d.parent_contract_id is null order by cc.confirmed_at limit 1);
   explanation:='Nhập nhầm email; email đúng trong hồ sơ: ';
  elsif p_kind='wrong_tenant' then
  select full_name into target_label from tenants where id=p_reference and id<>c.tenant_id and is_active;
  explanation:='Chọn nhầm khách; hồ sơ đúng: ';
 elsif p_kind='wrong_room' then
  select name into target_label from rooms where id=p_reference and id<>c.room_id;
  explanation:='Chọn nhầm phòng; phòng đúng: ';
 elsif p_kind='duplicate' then
  select * into retained from contracts where id=p_reference and id<>c.id and status='active' and room_id=c.room_id and tenant_id=c.tenant_id;
  if retained.id is not null and contract_term_values(to_jsonb(retained))-'revision_no' is not distinct from contract_term_values(to_jsonb(c))-'revision_no' then target_label:=retained.id; end if;
  explanation:='Lập trùng; giữ hợp đồng: ';
 else raise exception 'Chọn lý do hủy hợp lệ.'; end if;
 if target_label is null then raise exception 'Hồ sơ đối chiếu không hợp lệ hoặc không khớp lý do hủy.'; end if;
 select cc.recipient_email into email from contract_confirmations cc join contract_drafts d on d.id=cc.draft_id
  where cc.contract_id=c.id and cc.confirmed_at is not null and d.parent_contract_id is null order by cc.confirmed_at limit 1;
 if p_kind<>'test_reset' and (email is null or email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then raise exception 'Không có email nhận thông báo từ hợp đồng đã xác nhận.'; end if;
 -- The internal operation still rechecks the policy in the same transaction.
 perform set_config('app.contract_revision_write','1',true);
 update contracts set cancellation_kind=p_kind,cancellation_reference=case when p_kind='test_reset' then c.id else p_reference end where id=c.id;
 result:=contract_cancel_internal(c.id,p_actor,left(explanation||target_label||'. '||btrim(p_reason),1000));
 if p_kind<>'test_reset' then
  insert into contract_cancellation_notices(contract_id,recipient,tenant_name,room_name,reason,cancelled_at)
   select c.id,email,c.tenant_name,r.name,case p_kind when 'wrong_email' then 'Nhập nhầm email nhận hợp đồng. ' when 'wrong_tenant' then 'Chọn nhầm hồ sơ khách thuê. ' when 'wrong_room' then 'Chọn nhầm phòng. ' else 'Lập trùng hợp đồng. ' end||btrim(p_reason),x.cancelled_at from contracts x join rooms r on r.id=x.room_id where x.id=c.id on conflict do nothing;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.contract_cancellation_check(p_contract text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts; r rooms; ic integer; rc integer; cc integer; uc integer; explanation text; registered_test boolean;
begin
 select * into c from contracts where id=p_contract;
 if c.id is null then raise exception 'Không tìm thấy hợp đồng.'; end if;
 select * into r from rooms where id=c.room_id;
 registered_test:=exists(select 1 from contract_test_designations where contract_id=c.id and room_id=c.room_id and tenant_id=c.tenant_id);
 select count(*) into ic from invoices where room_id=c.room_id and tenant_id=c.tenant_id and
  (payment_status not in ('cancelled','merged') or coalesce(paid_amount,0)>0 or coalesce(deposit_applied,0)>0 or coalesce(payment_records,'[]'::jsonb)<>'[]'::jsonb or payment_date is not null or coalesce(electric_usage,0)>0 or coalesce(water_usage,0)>0);
 select count(*) into rc from move_in_receipts where room_id=c.room_id and tenant_id=c.tenant_id and (payment_status<>'cancelled' or payment_date is not null);
 select count(*) into cc from cash_transactions where room_id=c.room_id and transaction_date>=c.move_in_date and amount<>0;
 select count(*) into uc from contract_usage_evidence where contract_id=c.id;
 uc:=uc+(select count(*) from asset_snapshots where contract_id=c.id or contract_id is null and room_id=c.room_id and tenant_id=c.tenant_id and recorded_at>=c.created_at)
  +(select count(*) from payment_events p join invoices i on i.id=p.invoice_id where i.room_id=c.room_id and i.tenant_id=c.tenant_id and p.amount<>0);
 explanation:=case when c.status<>'active' then 'Hợp đồng không còn hiệu lực.'
  when c.original_confirmed_at is null then 'Không có mốc xác nhận đầu tiên. Dùng Trả phòng / chấm dứt hợp đồng.'
  when not registered_test and (now()<c.original_confirmed_at or now()>=c.original_confirmed_at+interval '24 hours') then 'Đã hết hạn hủy do lập nhầm (24 giờ từ lần xác nhận đầu tiên). Dùng Trả phòng / chấm dứt hợp đồng.'
  when ic+rc+cc>0 or coalesce(c.deposit_pre_collected,false) or coalesce(c.migration_debt,0)<>0 or coalesce(r.old_debt,0)<>0 then 'Đã có hóa đơn, công nợ, tiền cọc hoặc lịch sử thanh toán. Dùng Trả phòng / chấm dứt hợp đồng.'
  when uc>0 or c.transfer_history is not null or coalesce(r.has_move_in_receipt,false) or r.electric_new is distinct from c.electric_init or r.water_new is distinct from c.water_init then 'Đã có bàn giao, sử dụng điện nước, chuyển phòng hoặc lịch sử nghiệp vụ. Dùng Trả phòng / chấm dứt hợp đồng.'
  else null end;
 return jsonb_build_object('allowed',explanation is null,'reason',coalesce(explanation,case when registered_test then 'Hợp đồng đã được đánh dấu thử nghiệm. Có thể hủy test khi chưa có tài chính hoặc bàn giao; giữ toàn bộ lịch sử.' else 'Đủ điều kiện kiểm tra hủy do lập nhầm. Chọn lý do và hồ sơ đối chiếu; backend kiểm tra lại khi hủy.' end),
  'isTestContract',registered_test,'status',c.status,'invoices',ic,'receipts',rc,'cashTransactions',cc,'usageEvidence',uc,'confirmedAt',c.original_confirmed_at,'deadline',c.original_confirmed_at+interval '24 hours',
  'notice',(select to_jsonb(n)-'attempt_id' from contract_cancellation_notices n where n.contract_id=c.id));
end $function$

CREATE OR REPLACE FUNCTION public.contract_cancellation_notice(p_contract text, p_actor uuid, p_action text, p_attempt uuid DEFAULT NULL::uuid, p_message text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n contract_cancellation_notices;
begin
 if not exists(select 1 from users where id=p_actor and role='admin' and status='active') then raise exception 'Chỉ admin được xử lý thông báo hủy.'; end if;
 -- Test cancellation has no notification, regardless of the calling UI.
 if p_action='claim' and exists(select 1 from contracts where id=p_contract and cancellation_kind='test_reset') then
  return jsonb_build_object('claimed',false,'status','suppressed');
 end if;
 if p_action='list' then return coalesce((select jsonb_agg(contract_id order by cancelled_at) from contract_cancellation_notices queued where status='pending' and not exists(select 1 from contracts c where c.id=queued.contract_id and c.cancellation_kind='test_reset')),'[]'::jsonb); end if;
 select * into n from contract_cancellation_notices where contract_id=p_contract for update;
 if n.contract_id is null then raise exception 'Không có thông báo hủy hợp đồng.'; end if;
 if p_action='claim' then
  if n.status not in ('pending','failed') then return jsonb_build_object('claimed',false,'status',n.status); end if;
  update contract_cancellation_notices set status='sending',attempt_id=gen_random_uuid(),attempted_at=now(),error=null where contract_id=p_contract returning * into n;
  return to_jsonb(n)||jsonb_build_object('claimed',true);
 elsif p_action in ('sent','failed','uncertain') then
  if n.attempt_id is distinct from p_attempt then raise exception 'Lượt gửi thông báo không hợp lệ.'; end if;
  if n.status<>'sending' then return jsonb_build_object('status',n.status); end if;
  if p_action='sent' and length(coalesce(p_message,'')) not between 1 and 128 then raise exception 'Thiếu mã thư Gmail.'; end if;
  update contract_cancellation_notices set status=p_action,sent_at=case when p_action='sent' then now() end,message_id=left(p_message,128),error=left(p_error,1000) where contract_id=p_contract;
  insert into contract_lifecycle_events(contract_id,event_type,actor,reason) values(p_contract,'cancellation_email_'||p_action,p_actor,case when p_action='sent' then 'Gmail đã nhận thư gửi tới '||n.recipient else 'Gửi tới '||n.recipient||': '||coalesce(left(p_error,800),'Chưa xác định kết quả gửi') end);
 else raise exception 'Thao tác thông báo không hợp lệ.'; end if;
 return jsonb_build_object('status',p_action);
end $function$

CREATE OR REPLACE FUNCTION public.contract_confirmation_accept_initial(p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contract_confirmations; d contract_drafts; f jsonb; t jsonb; cid text; account tenant_web_accounts;
begin
  select * into c from contract_confirmations where token_hash=p_hash for update;
  if c.id is null or c.status in ('failed','revoked') or c.expires_at<=now() then raise exception 'Link không hợp lệ hoặc đã hết hạn.'; end if;
  if c.status='confirmed' then return jsonb_build_object('confirmed',true,'contractId',c.contract_id,'requirePassword',c.account_ready_at is null); end if;
  select * into d from contract_drafts where id=c.draft_id for update;
  if d.status<>'draft' or d.revision<>c.revision then raise exception 'Hợp đồng đã thay đổi hoặc đã đóng. Liên hệ chủ nhà.'; end if;
  perform 1 from rooms where id=d.room_id and status='vacant' for update;
  if not found then raise exception 'Phòng không còn trống.'; end if;
  perform 1 from tenants where id=d.tenant_id and is_active and lower(btrim(email))=c.recipient_email for update;
  if not found then raise exception 'Thông tin khách thuê đã thay đổi.'; end if;
  if exists(select 1 from contracts where status='active' and (room_id=d.room_id or tenant_id=d.tenant_id)) then raise exception 'Phòng hoặc khách đã có hợp đồng hiệu lực.'; end if;
  if not exists(select 1 from users where id=c.created_by and role='admin' and status='active') then raise exception 'Người lập hợp đồng không còn quyền quản trị.'; end if;
  f:=c.snapshot->'form'; t:=c.snapshot->'tenant'; cid:='contract_'||c.id::text;
  insert into contracts(id,room_id,tenant_id,tenant_name,tenant_phone,tenant_id_card,tenant_id_card_issued_date,tenant_id_card_issued_place,tenant_address,
    base_rent,deposit_amount,move_in_date,duration_months,expiration_date,invoice_day,occupant_count,billing_cycle,electric_init,water_init,notes,status,created_at)
    values(cid,d.room_id,d.tenant_id,t->>'full_name',t->>'phone',t->>'identity_card',nullif(t->>'id_card_issued_date','')::date,t->>'id_card_issued_place',t->>'address',
      (f->>'baseRent')::integer,(f->>'depositAmount')::integer,(f->>'moveInDate')::date,(f->>'durationMonths')::integer,
      case when (f->>'durationMonths')::integer=0 then null else ((f->>'moveInDate')::date+make_interval(months=>(f->>'durationMonths')::integer))::date end,
      (f->>'invoiceDay')::integer,(f->>'occupantCount')::integer,1,(f->>'electricInitial')::integer,(f->>'waterInitial')::integer,f->>'additionalTerms','active',c.created_at);
  update rooms set status='occupied',tenant_name=t->>'full_name',tenant_phone=t->>'phone',tenant_email=c.recipient_email,tenant_id_card=t->>'identity_card',
    move_in_date=(f->>'moveInDate')::date,base_rent=(f->>'baseRent')::integer,invoice_day=(f->>'invoiceDay')::integer,
    electric_old=(f->>'electricInitial')::integer,electric_new=(f->>'electricInitial')::integer,water_old=(f->>'waterInitial')::integer,water_new=(f->>'waterInitial')::integer,
    contract_expiration=case when (f->>'durationMonths')::integer=0 then null else ((f->>'moveInDate')::date+make_interval(months=>(f->>'durationMonths')::integer))::date end,
    has_move_in_receipt=false,expected_end_date=null where id=d.room_id;
  update contract_drafts set status='confirmed',revision=revision+1 where id=d.id;
  select * into account from tenant_web_accounts where tenant_id=d.tenant_id;
  if account.tenant_id is not null and (account.status='locked' or account.email<>c.recipient_email) then raise exception 'Tài khoản khách đang khóa hoặc email đã thay đổi. Liên hệ chủ nhà.'; end if;
  update contract_confirmations set status='confirmed',confirmed_at=now(),contract_id=cid,
    account_ready_at=case when account.tenant_id is not null then now() else null end where id=c.id;
  return jsonb_build_object('confirmed',true,'contractId',cid,'requirePassword',account.tenant_id is null);
end $function$

CREATE OR REPLACE FUNCTION public.contract_confirmation_accept(p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contract_confirmations; d contract_drafts; original contracts; f jsonb; ready timestamptz;
begin
 perform pg_advisory_xact_lock(hashtext('contract-lifecycle'));
 select * into c from contract_confirmations where token_hash=p_hash for update;
 select * into d from contract_drafts where id=c.draft_id for update;
 if d.parent_contract_id is null then
  -- A corrected contract for the same verified tenant may reuse their existing
  -- account. Unlock only within acceptance; any failed validation rolls it back.
  if c.status in ('prepared','sent','viewed') and c.expires_at>now() and d.status='draft' and d.revision=c.revision and
   exists(select 1 from tenant_web_accounts a join contract_lifecycle_events e on e.cancelled_account_version=a.session_version and e.event_type='cancelled'
    join contracts previous on previous.id=e.contract_id and previous.tenant_id=a.tenant_id
    where a.tenant_id=d.tenant_id and a.email=c.recipient_email and a.status='locked' and a.activated_at is not null) then
   perform webmobile_revoke_tenant(d.tenant_id,'unlock');
  end if;
  return contract_confirmation_accept_initial(p_hash);
 end if;
 lock table invoices in share row exclusive mode;
 if c.id is null or c.status in ('failed','revoked') or c.expires_at<=now() then raise exception 'Link không hợp lệ hoặc đã hết hạn.'; end if;
 if c.status='confirmed' then return jsonb_build_object('confirmed',true,'contractId',c.contract_id,'requirePassword',c.account_ready_at is null); end if;
 select * into original from contracts where id=d.parent_contract_id for update;
 perform 1 from rooms where id=original.room_id for update;
 if d.status<>'draft' or d.revision<>c.revision or original.status<>'active' or contract_term_values(to_jsonb(original)) is distinct from d.base_contract then raise exception 'Bản sửa hoặc hợp đồng gốc đã thay đổi. Liên hệ chủ nhà.'; end if;
 if not exists(select 1 from users where id=c.created_by and role='admin' and status='active') or
  not exists(select 1 from tenants where id=d.tenant_id and is_active and lower(btrim(email))=c.recipient_email) then raise exception 'Hồ sơ hoặc quyền người lập đã thay đổi.'; end if;
 f:=c.snapshot->'form';
 if f->>'moveInDate' is distinct from original.move_in_date::text and exists(select 1 from invoices where room_id=original.room_id and tenant_id=original.tenant_id) then raise exception 'Đã có hóa đơn, không đổi ngày vào.'; end if;
 perform set_config('app.contract_revision_write','1',true);
 update contracts set base_rent=(f->>'baseRent')::integer,deposit_amount=(f->>'depositAmount')::integer,move_in_date=(f->>'moveInDate')::date,
  duration_months=(f->>'durationMonths')::integer,expiration_date=case when (f->>'durationMonths')::integer=0 then null else ((f->>'moveInDate')::date+make_interval(months=>(f->>'durationMonths')::integer))::date end,
  invoice_day=(f->>'invoiceDay')::integer,occupant_count=(f->>'occupantCount')::integer,notes=f->>'additionalTerms',revision_no=revision_no+1 where id=original.id;
 update rooms set base_rent=(f->>'baseRent')::integer,invoice_day=(f->>'invoiceDay')::integer,move_in_date=(f->>'moveInDate')::date,
  contract_expiration=case when (f->>'durationMonths')::integer=0 then null else ((f->>'moveInDate')::date+make_interval(months=>(f->>'durationMonths')::integer))::date end where id=original.room_id;
 -- Leave current meter readings, existing invoices, receipts and bank records intact.
 update contract_drafts set status='confirmed',revision=revision+1 where id=d.id;
 select activated_at into ready from tenant_web_accounts where tenant_id=original.tenant_id and status='active' and email=c.recipient_email;
 if ready is null then
  if exists(select 1 from tenant_web_accounts where tenant_id=original.tenant_id) then raise exception 'Tài khoản khách đang khóa hoặc email đã thay đổi. Liên hệ chủ nhà.'; end if;
  update contract_confirmations set status='revoked' where contract_id=original.id and status='confirmed' and account_ready_at is null;
 end if;
 update contract_confirmations set status='confirmed',confirmed_at=now(),contract_id=original.id,account_ready_at=case when ready is not null then now() else null end where id=c.id;
 insert into contract_lifecycle_events(contract_id,draft_id,event_type,actor,reason,before_snapshot,after_snapshot)
  values(original.id,d.id,'amendment_applied',c.created_by,c.snapshot#>>'{amendment,reason}',d.before_snapshot,c.snapshot);
 return jsonb_build_object('confirmed',true,'contractId',original.id,'requirePassword',ready is null);
end $function$

CREATE OR REPLACE FUNCTION public.contract_confirmation_create_initial(p_draft uuid, p_revision integer, p_hash text, p_actor uuid, p_document text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d contract_drafts; prior contract_confirmations; f jsonb; reading text;
begin
  if not exists(select 1 from users where id=p_actor and role='admin' and status='active') then raise exception 'Chỉ admin được gửi hợp đồng.'; end if;
  select * into d from contract_drafts where id=p_draft for update;
  if d.id is null or d.status<>'draft' or d.revision<>p_revision then raise exception 'Bản nháp đã thay đổi hoặc đã đóng.'; end if;
  if not exists(select 1 from tenants where id=d.tenant_id and is_active and lower(btrim(email))=lower(btrim(d.recipient_email))) then raise exception 'Email hồ sơ đã thay đổi. Lưu lại bản nháp.'; end if;
  select * into prior from contract_confirmations where draft_id=p_draft order by created_at desc limit 1;
  if prior.id is not null and prior.revision=p_revision and prior.status not in ('failed','revoked') and prior.expires_at>now() then
    raise exception 'Hợp đồng đã được gửi hoặc đang gửi. Không gửi trùng; kiểm tra trạng thái trước.';
  end if;
  f:=d.snapshot->'form';
  if coalesce((f->>'baseRent')::bigint,0)<=0 or coalesce((f->>'depositAmount')::bigint,-1)<0 or
     coalesce((f->>'invoiceDay')::integer,0) not between 1 and 28 or
     coalesce((f->>'occupantCount')::integer,0) not between 1 and 20 or
     coalesce((f->>'durationMonths')::integer,-1) not between 0 and 120 then raise exception 'Nội dung hợp đồng chưa hợp lệ.'; end if;
  perform (f->>'moveInDate')::date;
  foreach reading in array array['electricInitial','waterInitial'] loop
    if coalesce(f->>reading,'') !~ '^\d+$' or (f->>reading)::bigint>2147483647 then raise exception 'Nhập đầy đủ chỉ số điện và nước bàn giao trước khi gửi.'; end if;
  end loop;
  if length(p_document)<100 or length(p_document)>200000 then raise exception 'Bản hợp đồng chưa đầy đủ.'; end if;
  update contract_confirmations set status='revoked' where draft_id=p_draft and status in ('prepared','sent','viewed');
  insert into contract_confirmations(draft_id,revision,token_hash,snapshot,document_html,recipient_email,created_by)
    values(d.id,d.revision,p_hash,d.snapshot,p_document,lower(btrim(d.recipient_email)),p_actor);
  return contract_confirmation_status(p_draft);
end $function$

CREATE OR REPLACE FUNCTION public.contract_confirmation_create(p_draft uuid, p_revision integer, p_hash text, p_actor uuid, p_document text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d contract_drafts; c contracts;
begin
 perform pg_advisory_xact_lock(hashtext('contract-lifecycle'));
 select * into d from contract_drafts where id=p_draft;
 if d.parent_contract_id is not null then
  select * into c from contracts where id=d.parent_contract_id;
  if c.status is distinct from 'active' or contract_term_values(to_jsonb(c)) is distinct from d.base_contract then raise exception 'Hợp đồng gốc đã thay đổi. Hủy bản sửa và tạo lại.'; end if;
  if d.snapshot->'form'=d.before_snapshot->'form' then raise exception 'Chưa thay đổi nội dung hợp đồng.'; end if;
 end if;
 return contract_confirmation_create_initial(p_draft,p_revision,p_hash,p_actor,p_document);
end $function$

CREATE OR REPLACE FUNCTION public.contract_confirmation_document_view(p_hash text, p_visit uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cid uuid;
begin
  if p_visit is null then raise exception 'Phiên xem hợp đồng không hợp lệ.'; end if;
  -- The same validation/row lock used to display the document prevents logging
  -- a changed, revoked or expired link. This is display telemetry, not proof of reading.
  perform contract_confirmation_view(p_hash);
  select id into cid from contract_confirmations where token_hash=p_hash;
  perform contract_confirmation_log_event(cid,'document_viewed',clock_timestamp(),p_visit);
end $function$

