CREATE OR REPLACE FUNCTION public.contract_confirmation_view_initial(p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contract_confirmations; d contract_drafts;
begin
  select * into c from contract_confirmations where token_hash=p_hash for update;
  if c.id is null or c.status in ('failed','revoked') or c.expires_at<=now() then raise exception 'Link không hợp lệ, đã bị hủy hoặc hết hạn.'; end if;
  select * into d from contract_drafts where id=c.draft_id;
  if d.revision<>c.revision and c.status<>'confirmed' or d.status='cancelled' then raise exception 'Hợp đồng đã thay đổi. Vui lòng liên hệ chủ nhà để nhận link mới.'; end if;
  if c.status in ('prepared','sent') then update contract_confirmations set status='viewed',viewed_at=coalesce(viewed_at,now()) where id=c.id; end if;
  return jsonb_build_object('html',c.document_html,'room',c.snapshot#>>'{room,name}','name',c.snapshot#>>'{tenant,full_name}',
    'email',c.recipient_email,'status',case when c.status='confirmed' then 'confirmed' else 'viewed' end,
    'expiresAt',c.expires_at,'requirePassword',c.status='confirmed' and c.account_ready_at is null);
end $function$

CREATE OR REPLACE FUNCTION public.contract_confirmation_view(p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare result jsonb; c contract_confirmations; d contract_drafts; original contracts;
begin
 perform pg_advisory_xact_lock(hashtext('contract-lifecycle'));
 result:=contract_confirmation_view_initial(p_hash);
 select * into c from contract_confirmations where token_hash=p_hash;
 select * into d from contract_drafts where id=c.draft_id;
 if d.parent_contract_id is not null then
  select * into original from contracts where id=d.parent_contract_id;
  if original.status<>'active' or (c.status<>'confirmed' and contract_term_values(to_jsonb(original)) is distinct from d.base_contract) then raise exception 'Hợp đồng gốc đã thay đổi hoặc bị hủy. Liên hệ chủ nhà.'; end if;
  result:=result||jsonb_build_object('amendment',c.snapshot->'amendment','newForm',c.snapshot->'form');
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.enqueue_due_server_emails(p_now timestamp with time zone DEFAULT now())
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cfg email_automation_settings%rowtype; today date:=(p_now at time zone 'Asia/Ho_Chi_Minh')::date;
 i record; r record; c record; due date; age integer; kind text; n integer:=0; bucket integer;
begin
 select * into cfg from email_automation_settings where enabled;
 if not found or extract(hour from p_now at time zone 'Asia/Ho_Chi_Minh')<cfg.reminder_hour then return 0; end if;
 for i in select v.*,invoice_room.name room_name from invoices v join rooms invoice_room on invoice_room.id=v.room_id
  where v.payment_status not in ('paid','cancelled','merged') and v.total_amount>coalesce(v.paid_amount,0) loop
  due:=coalesce(i.due_date,make_date(i.year,i.month,15));
  if due>today then continue; end if;
  age:=today-due; kind:=case when age>=cfg.long_unpaid_days then 'rent_long_unpaid' else 'rent_overdue' end;
  bucket:=age/cfg.repeat_days;
  n:=n+enqueue_server_email(kind,i.id||':'||due||':'||bucket,
    jsonb_build_object('invoiceId',i.id,'roomId',i.room_id,'roomName',i.room_name,'dueDate',due,'daysUnpaid',age));
 end loop;
 for r in select * from rooms where old_debt>0 loop
  -- Imported room debt is separate from invoice debt and must remain visible
  -- even when newer invoices are also unpaid.
  if extract(day from today)<15 then continue; end if;
  n:=n+enqueue_server_email('rent_overdue',r.id||':old-debt:'||to_char(today,'YYYY-MM')||':'||((extract(day from today)::integer-15)/cfg.repeat_days),
    jsonb_build_object('roomId',r.id,'roomName',r.name,'oldDebt',true,'dueDate',date_trunc('month',today)::date+14));
 end loop;
 for r in select * from rooms where status='ending' and expected_end_date<=today loop
  n:=n+enqueue_server_email('room_checkout_due',r.id||':'||r.expected_end_date||':'||((today-r.expected_end_date)/cfg.repeat_days),
    jsonb_build_object('roomId',r.id,'roomName',r.name,'dueDate',r.expected_end_date));
 end loop;
 for c in select candidate_contract.*,contract_room.name room_name from contracts candidate_contract join rooms contract_room on contract_room.id=candidate_contract.room_id
  where candidate_contract.status='active' and candidate_contract.expiration_date between today and today+7 loop
  n:=n+enqueue_server_email('contract_expiring',c.id||':'||c.expiration_date,
    jsonb_build_object('contractId',c.id,'roomId',c.room_id,'roomName',c.room_name,'dueDate',c.expiration_date));
 end loop;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.ensure_tenant_payment_cycle(p_user uuid, p_contract text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts%rowtype; r rooms%rowtype; z service_zones%rowtype; v invoices%rowtype;
 cy tenant_payment_cycles%rowtype; today date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date;
 m date:=date_trunc('month',today)::date; due date; old_e int; old_w int; days int; linked text; enrolled date;
begin
 c:=tenant_payment_scope(p_user,p_contract);
 perform pg_advisory_xact_lock(20261005,120000);
 perform pg_advisory_xact_lock(hashtext('tenant-cycle:'||c.id));
 select * into c from contracts where id=c.id for update;
 select * into r from rooms where id=c.room_id for update;
 if r.status<>'occupied' then return null;end if;
 -- No invented charges for non-monthly or unsettled room transfers.
 if coalesce(c.billing_cycle,1)<>1 or (c.transfer_history is not null and nullif(c.transfer_history->>'history_billed_in_invoice_id','') is null) then return null;end if;
 select * into z from service_zones where id=r.service_zone_id;
 if not found or z.electric_price is null or z.water_price is null then return null;end if;
 select (a.created_at at time zone 'Asia/Ho_Chi_Minh')::date into enrolled from tenant_web_accounts a where a.auth_user_id=p_user;
 due:=m+least(greatest(coalesce(c.invoice_day,5),1),extract(day from m+interval '1 month' - interval '1 day')::int)-1;
 -- Opening is automatic only when the agreed invoice day has arrived.
 if today<due or c.move_in_date>due or enrolled>today then return null;end if;
 select * into cy from tenant_payment_cycles where contract_id=c.id and invoice_id is null order by period limit 1;
 if found then return cy.id;end if;
 select * into cy from tenant_payment_cycles where contract_id=c.id and period=m;
 if found then return cy.id;end if;
 select * into v from invoices i where i.room_id=c.room_id and i.tenant_id=c.tenant_id
 and (i.web_contract_id=c.id or (i.web_contract_id is null and i.created_at>=c.created_at))
 and i.payment_status not in ('cancelled','merged') and i.month=extract(month from m) and i.year=extract(year from m)
 and (i.billing_reason in ('monthly','first_month','room_cycle') or i.is_first_month)
 order by i.created_at desc limit 1;
 linked:=v.id;
 if linked is not null then old_e:=coalesce(v.electric_old,c.electric_init);old_w:=coalesce(v.water_old,c.water_init);
 else
  select * into v from invoices i where i.room_id=c.room_id and i.tenant_id=c.tenant_id
   and (i.web_contract_id=c.id or (i.web_contract_id is null and i.created_at>=c.created_at))
   and i.payment_status not in ('cancelled','merged') and coalesce(i.billing_period_end,i.invoice_date,make_date(i.year,i.month,1))<m
   and i.billing_reason in ('monthly','first_month','contract_end') order by coalesce(i.billing_period_end,i.invoice_date) desc,i.created_at desc limit 1;
  old_e:=coalesce(v.electric_new,c.electric_init);old_w:=coalesce(v.water_new,c.water_init);
 end if;
 if old_e is null or old_w is null or old_e<0 or old_w<0 then return null;end if;
 -- First-month deposits/proration remain in the existing initial invoice.
 -- A new tenant does not receive a full-month monthly invoice in move-in month.
 if linked is null and date_trunc('month',c.move_in_date)::date=m and not coalesce(c.is_migration,false) then return null;end if;
 days:=greatest(1,due-coalesce(v.billing_period_end,c.move_in_date));
 insert into tenant_payment_cycles(contract_id,tenant_id,room_id,period,opened_on,period_start,period_end,revision,
 electric_old,water_old,electric_price,water_price,room_cost,wifi_cost,garbage_cost,elapsed_days,invoice_id)
 values(c.id,c.tenant_id,c.room_id,m,due,m,(m+interval '1 month' - interval '1 day')::date,coalesce(c.revision_no,1),
 old_e,old_w,z.electric_price,z.water_price,c.base_rent,coalesce(z.internet_price,0),coalesce(z.cleaning_price,0),days,linked)
 returning id into cy.id;
 return cy.id;
end $function$

CREATE OR REPLACE FUNCTION public.install_email_automation_schedule()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare secret text;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'Service only' using errcode='42501';
  end if;
  select decrypted_secret into secret
  from vault.decrypted_secrets
  where name='EMAIL_AUTOMATION_SECRET'
  order by created_at desc
  limit 1;
  if nullif(secret,'') is null then return false; end if;
  if exists(select 1 from cron.job where jobname='ankhang-email-automation') then
    perform cron.unschedule('ankhang-email-automation');
  end if;
  perform cron.schedule(
    'ankhang-email-automation',
    '*/2 * * * *',
    $job$select net.http_post(
      url := 'https://wtrycmiojsiliyjxsewz.supabase.co/functions/v1/email-automation',
      headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer ' || (select decrypted_secret from vault.decrypted_secrets where name='EMAIL_AUTOMATION_SECRET' order by created_at desc limit 1)),
      body := '{}'::jsonb
    ) as request_id;$job$
  );
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.process_server_sepay(p_tx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cfg email_automation_settings%rowtype; tx_key text; tx_id text; ref text; amount bigint; content text;
 occurred timestamptz; account text; keys text[]; ids text[]; inv invoices%rowtype; actor uuid; answer jsonb;
 state text; saved_claims text; saved_sub text; matched_room text; ctr contracts%rowtype;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service only' using errcode='42501'; end if;
 select * into cfg from email_automation_settings where enabled and sepay_enabled;
 if not found then return jsonb_build_object('status','disabled'); end if;
 tx_id:=nullif(btrim(p_tx->>'id'),'');ref:=nullif(btrim(p_tx->>'reference_number'),'');
 amount:=(p_tx->>'amount_in')::numeric;content:=coalesce(p_tx->>'transaction_content','');
 if tx_id is null or amount is null or amount<=0 or amount>2147483647 or (p_tx->>'amount_in')::numeric<>amount then return jsonb_build_object('status','ignored');end if;
 if nullif(p_tx->>'transaction_date','') is null then return jsonb_build_object('status','ignored');end if;
 occurred:=case when p_tx->>'transaction_date' ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' then (p_tx->>'transaction_date')::timestamptz
   else (p_tx->>'transaction_date')::timestamp at time zone 'Asia/Ho_Chi_Minh' end;
 if occurred>now()+interval '5 minutes' then return jsonb_build_object('status','ignored');end if;
 select upper(regexp_replace(account_no,'[^A-Z0-9]','','gi')) into account from app_settings limit 1;
 if nullif(account,'') is null or not (
   upper(regexp_replace(coalesce(p_tx->>'account_number',''),'[^A-Z0-9]','','gi'))=upper(regexp_replace(account,'[^A-Z0-9]','','g'))
   or upper(regexp_replace(coalesce(p_tx->>'sub_account',''),'[^A-Z0-9]','','gi'))=upper(regexp_replace(account,'[^A-Z0-9]','','g'))
 ) then return jsonb_build_object('status','wrong_account');end if;
 if coalesce((p_tx->>'amount_out')::numeric,0)<>0 then return jsonb_build_object('status','ignored');end if;
 tx_key:=regexp_replace(upper(coalesce(ref,tx_id)),'[^A-Z0-9]','','g');
 keys:=array[lower(coalesce(ref,tx_id)),lower(tx_id)];
 -- Serialize with invoice/wallet operations before taking external-key and row locks.
 perform pg_advisory_xact_lock(20261005,120000);
 perform pg_advisory_xact_lock(hashtext('server-sepay:'||tx_key));
 if exists(select 1 from sepay_server_transactions where transaction_key=tx_key or external_id=tx_id) then return jsonb_build_object('status','duplicate');end if;
 if occurred<cfg.sepay_started_at then return jsonb_build_object('status','historical');end if;
 if exists(select 1 from payment_event_keys where key=any(keys)) or exists(
  select 1 from invoices i cross join lateral jsonb_array_elements(coalesce(i.payment_records,'[]')) p
   where lower(btrim(p->>'external_ref'))=any(keys) or lower(btrim(p->>'external_id'))=any(keys)) then
  state:='recorded';
 else
  select array_agg(i.id) into ids from invoices i join rooms r on r.id=i.room_id
  where i.payment_status not in ('cancelled','merged') and position(
   'P'||coalesce(nullif(regexp_replace(r.name,'\D','','g'),''),nullif(left(regexp_replace(upper(r.name),'[^A-Z0-9]','','g'),6),''),'XX')||
   'T'||lpad(i.month::text,2,'0')||i.year||'C'||right(regexp_replace(upper(i.id),'[^A-Z0-9]','','g'),12)
   in regexp_replace(upper(content),'[^A-Z0-9]','','g'))>0;
  state:=case when coalesce(cardinality(ids),0)=0 then 'unmatched' when cardinality(ids)>1 then 'ambiguous' else 'partial' end;
  if cardinality(ids)=1 then
   select * into inv from invoices where id=ids[1] for update;
   if amount=inv.total_amount-coalesce(inv.paid_amount,0) and inv.payment_status<>'paid' and inv.total_amount>0 then
    select id into actor from users where role='admin' and status='active' order by created_at,id limit 1;
    if actor is null then raise exception 'Chưa có quản trị viên để ghi nhận SePay.';end if;
    saved_claims:=current_setting('request.jwt.claims',true);saved_sub:=current_setting('request.jwt.claim.sub',true);
    perform set_config('request.jwt.claim.sub',actor::text,true);
    perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','service_role')::text,true);
    answer:=record_invoice_payment_atomic(inv.id,amount::integer,'transfer',(occurred at time zone 'Asia/Ho_Chi_Minh')::date,
      'Thu qua SePay: '||content||' (Ref: '||coalesce(ref,tx_id)||')',ref,tx_id,'sepay');
    perform set_config('request.jwt.claim.sub',coalesce(saved_sub,''),true);
    perform set_config('request.jwt.claims',coalesce(saved_claims,'{}'),true);
    if coalesce((answer->>'applied')::boolean,false) or coalesce((answer->>'duplicate')::boolean,false) then state:='recorded';
    else raise exception 'Khoản thu SePay chưa được ghi nhận.';end if;
    -- Complete the same settlement transition that Electron performs, atomically.
    if (answer->>'transitioned_to_paid')::boolean and inv.is_settlement then
     select * into ctr from contracts where room_id=inv.room_id and status='active' order by created_at desc limit 1 for update;
     if ctr.id is not null and (ctr.tenant_id is null or ctr.tenant_id=inv.tenant_id) then
      update rooms set status='vacant',tenant_name=null,tenant_phone=null,move_in_date=null,expected_end_date=null,
       electric_old=inv.electric_new,electric_new=inv.electric_new,water_old=inv.water_new,water_new=inv.water_new,has_move_in_receipt=false
       where id=inv.room_id and status='ending';
      if found then update contracts set status='terminated',end_date=coalesce(inv.invoice_date,(occurred at time zone 'Asia/Ho_Chi_Minh')::date),
       end_note=coalesce(inv.damage_note,inv.adjustment_note),final_electric=inv.electric_new,final_water=inv.water_new where id=ctr.id;end if;
     end if;
    end if;
   else state:=case when amount<inv.total_amount-coalesce(inv.paid_amount,0) then 'partial' else 'over' end;end if;
  end if;
 end if;
 insert into sepay_server_transactions(transaction_key,external_id,reference_number,amount,content,occurred_at,invoice_id,status)
 values(tx_key,tx_id,ref,amount,content,occurred,inv.id,state);
 if state<>'recorded' then
  select name into matched_room from rooms where id=inv.room_id;
  perform enqueue_server_email('sepay_unmatched',tx_key,jsonb_build_object('transactionKey',coalesce(ref,tx_id),'amount',amount,
   'content',content,'roomName',matched_room,'reviewStatus',state,'invoiceId',inv.id));
 end if;
 return jsonb_build_object('status',state,'invoiceId',inv.id);
end $function$

CREATE OR REPLACE FUNCTION public.queue_tenant_payment_emails()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a record; cy tenant_payment_cycles%rowtype; cid uuid; kind text; n int:=0; added int;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service only';end if;
 if not exists(select 1 from email_automation_settings where enabled) then return 0;end if;
 for a in select ac.auth_user_id,ac.email,c.id from tenant_web_accounts ac join contracts c on c.tenant_id=ac.tenant_id
  join tenants t on t.id=c.tenant_id where ac.status='active' and c.status='active' and t.is_active loop
  cid:=ensure_tenant_payment_cycle(a.auth_user_id,a.id);
  for cy in select * from tenant_payment_cycles where contract_id=a.id loop
   kind:=case when cy.invoice_id is null then 'readings' when exists(select 1 from invoices where id=cy.invoice_id and payment_status='paid') then 'receipt' else 'invoice' end;
   insert into tenant_payment_emails(cycle_id,kind,recipient) values(cy.id,kind,a.email) on conflict do nothing;
   get diagnostics added=row_count;n:=n+added;
  end loop;
 end loop;
 -- Keep confirmed photo evidence for the tenancy; discard failed/expired previews.
 delete from tenant_meter_photos where confirmed_at is null and expires_at<now()-interval '1 day';
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_wallet_balances(p_bank bigint, p_cash bigint, p_expected_total bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare position jsonb; result public.wallet_reconciliations%rowtype; ids text[];
begin
  if not exists(select 1 from public.users u where u.id = auth.uid() and u.status = 'active' and u.role = 'admin') then
    raise exception 'Chỉ quản trị viên được xác nhận đối soát.' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(20261005, 120000);
  select * into result from public.wallet_reconciliations limit 1;
  if found then
    if result.bank_balance = p_bank and result.cash_balance = p_cash then return to_jsonb(result); end if;
    raise exception 'Đã chốt số dư một lần. Không được điều chỉnh lặp lại.';
  end if;
  if p_bank is null or p_cash is null or p_bank < 0 or p_cash < 0 or nullif(btrim(p_reason), '') is null then
    raise exception 'Số dư thực tế và lý do đối soát không hợp lệ.';
  end if;
  position := public.wallet_position();
  if p_expected_total is null or (position->>'total')::bigint <> p_expected_total
    or p_bank + p_cash <> p_expected_total then
    raise exception 'Tổng sổ đã thay đổi hoặc số dư xác nhận không khớp tổng tiền. Tải lại và đối soát; không tự tạo tiền bù.';
  end if;
  select coalesce(array_agg(entry_id order by entry_id), '{}'::text[]) into ids from (
    select 'cash-' || id as entry_id from public.cash_transactions
    union all
    select 'invoice-' || i.id || '-' || (p->>'id') from public.invoices i
    cross join lateral jsonb_array_elements(coalesce(i.payment_records, '[]'::jsonb)) p
  ) existing_entries;
  if array_position(ids, null) is not null then raise exception 'Có thanh toán cũ thiếu mã lịch sử, cần kiểm tra trước khi khóa.'; end if;
  insert into public.wallet_reconciliations(bank_balance, cash_balance, bank_balance_before, cash_balance_before,
    total_before, entry_ids, confirmed_by, reason)
  values(p_bank, p_cash, (position->>'bank')::bigint, (position->>'cash')::bigint, p_expected_total, ids, auth.uid(), btrim(p_reason))
  returning * into result;
  return to_jsonb(result);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_invoice_payment_atomic(p_invoice_id text, p_amount integer, p_payment_method text, p_payment_date date, p_note text DEFAULT NULL::text, p_external_ref text DEFAULT NULL::text, p_external_id text DEFAULT NULL::text, p_source text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
  invoice_row public.invoices%rowtype;
  updated_row public.invoices%rowtype;
  event_id uuid;
  duplicate_invoice_id text;
  ref_key text := nullif(lower(btrim(p_external_ref)), '');
  id_key text := nullif(lower(btrim(p_external_id)), '');
  current_paid integer;
  new_paid integer;
  next_status text;
  payment_record jsonb;
  transitioned_to_paid boolean;
begin
  if actor_id is null or not exists (
    select 1
    from public.users as u
    where u.id = actor_id and u.status = 'active'
  ) then
    raise exception 'Phiên đăng nhập không hợp lệ hoặc tài khoản đã bị vô hiệu hóa.'
      using errcode = '42501';
  end if;

  if p_amount is null or p_amount = 0 then
    raise exception 'Số tiền thu không hợp lệ.';
  end if;

  if p_payment_method not in ('cash', 'transfer') then
    raise exception 'Phương thức thanh toán không hợp lệ.';
  end if;

  if p_payment_date is null then
    raise exception 'Ngày thanh toán không hợp lệ.';
  end if;

  if lower(coalesce(p_source, '')) = 'sepay' and ref_key is null and id_key is null then
    raise exception 'Giao dịch SePay thiếu mã đối soát.';
  end if;

  select *
  into invoice_row
  from public.invoices
  where id = p_invoice_id
  for update;

  if not found then
    raise exception 'Không tìm thấy hóa đơn.';
  end if;

  if invoice_row.payment_status in ('cancelled', 'merged') then
    raise exception 'Không thể ghi nhận tiền vào hóa đơn đã hủy hoặc đã gộp.';
  end if;

  -- Detect keys already stored in legacy JSON payment records without altering them.
  if ref_key is not null or id_key is not null then
    select i.id
    into duplicate_invoice_id
    from public.invoices as i
    cross join lateral jsonb_array_elements(
      case
        when jsonb_typeof(i.payment_records) = 'array' then i.payment_records
        else '[]'::jsonb
      end
    ) as record(value)
    where (
      ref_key is not null
      and ref_key in (
        nullif(lower(btrim(record.value->>'external_ref')), ''),
        nullif(lower(btrim(record.value->>'external_id')), '')
      )
    ) or (
      id_key is not null
      and id_key in (
        nullif(lower(btrim(record.value->>'external_ref')), ''),
        nullif(lower(btrim(record.value->>'external_id')), '')
      )
    )
    limit 1;

    if duplicate_invoice_id is not null then
      if duplicate_invoice_id = p_invoice_id then
        return jsonb_build_object(
          'invoice', to_jsonb(invoice_row),
          'applied', false,
          'duplicate', true,
          'transitioned_to_paid', false
        );
      end if;
      raise exception 'Giao dịch này đã được ghi nhận cho một hóa đơn khác.';
    end if;

    select k.invoice_id
    into duplicate_invoice_id
    from public.payment_event_keys as k
    where k.key in (ref_key, id_key)
    limit 1;

    if duplicate_invoice_id is not null then
      if duplicate_invoice_id = p_invoice_id then
        return jsonb_build_object(
          'invoice', to_jsonb(invoice_row),
          'applied', false,
          'duplicate', true,
          'transitioned_to_paid', false
        );
      end if;
      raise exception 'Giao dịch này đã được ghi nhận cho một hóa đơn khác.';
    end if;
  end if;

  if invoice_row.payment_status = 'paid' then
    return jsonb_build_object(
      'invoice', to_jsonb(invoice_row),
      'applied', false,
      'duplicate', false,
      'transitioned_to_paid', false
    );
  end if;

  current_paid := coalesce(invoice_row.paid_amount, 0);
  new_paid := current_paid + p_amount;

  if coalesce(invoice_row.total_amount, 0) > 0 then
    if p_amount < 0 or new_paid > invoice_row.total_amount then
      raise exception 'Số tiền vượt quá số tiền còn phải thu của hóa đơn.';
    end if;
    next_status := case when new_paid = invoice_row.total_amount then 'paid' else 'partial' end;
  elsif coalesce(invoice_row.total_amount, 0) < 0 then
    if p_amount > 0 or new_paid < invoice_row.total_amount then
      raise exception 'Số tiền hoàn vượt quá giá trị phải hoàn của hóa đơn.';
    end if;
    next_status := case when new_paid = invoice_row.total_amount then 'paid' else 'partial' end;
  else
    raise exception 'Hóa đơn có tổng tiền bằng 0, không thể ghi nhận thêm thanh toán.';
  end if;

  begin
    insert into public.payment_events (
      invoice_id, amount, payment_method, payment_date, note,
      external_ref, external_id, source, created_by
    )
    values (
      p_invoice_id, p_amount, p_payment_method, p_payment_date, p_note,
      nullif(btrim(p_external_ref), ''), nullif(btrim(p_external_id), ''),
      nullif(btrim(p_source), ''), actor_id
    )
    returning id into event_id;

    insert into public.payment_event_keys (key, event_id, invoice_id)
    select distinct candidate.key, event_id, p_invoice_id
    from (
      values (ref_key), (id_key)
    ) as candidate(key)
    where candidate.key is not null
    order by candidate.key;
  exception
    when unique_violation then
      select k.invoice_id
      into duplicate_invoice_id
      from public.payment_event_keys as k
      where k.key in (ref_key, id_key)
      limit 1;

      if duplicate_invoice_id = p_invoice_id then
        return jsonb_build_object(
          'invoice', to_jsonb(invoice_row),
          'applied', false,
          'duplicate', true,
          'transitioned_to_paid', false
        );
      end if;
      raise exception 'Giao dịch này đã được ghi nhận cho một hóa đơn khác.';
  end;

  payment_record := jsonb_strip_nulls(jsonb_build_object(
    'id', 'pay-' || replace(gen_random_uuid()::text, '-', ''),
    'amount', p_amount,
    'payment_method', p_payment_method,
    'payment_date', p_payment_date,
    'note', p_note,
    'external_ref', nullif(btrim(p_external_ref), ''),
    'external_id', nullif(btrim(p_external_id), ''),
    'source', nullif(btrim(p_source), ''),
    'created_at', now()
  ));

  transitioned_to_paid := invoice_row.payment_status is distinct from 'paid' and next_status = 'paid';

  update public.invoices
  set paid_amount = new_paid,
      payment_status = next_status,
      payment_method = p_payment_method,
      payment_date = p_payment_date,
      payment_records = coalesce(payment_records, '[]'::jsonb) || jsonb_build_array(payment_record)
  where id = p_invoice_id
  returning * into updated_row;

  return jsonb_build_object(
    'invoice', to_jsonb(updated_row),
    'applied', true,
    'duplicate', false,
    'transitioned_to_paid', transitioned_to_paid
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reopen_invoice_debt_atomic(p_invoice_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid := auth.uid();
  actor_role text;
  invoice_row public.invoices%rowtype;
  room_row public.rooms%rowtype;
begin
  select u.role into actor_role
  from public.users u
  where u.id = actor_id and u.status = 'active';
  if actor_id is null or actor_role is distinct from 'admin' then
    raise exception 'Chỉ quản trị viên mới được hoàn tác chốt nợ.' using errcode = '42501';
  end if;

  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then raise exception 'Không tìm thấy hóa đơn.'; end if;
  if invoice_row.debt_confirmed_at is null then
    return jsonb_build_object('invoice', to_jsonb(invoice_row), 'applied', false);
  end if;
  if invoice_row.paid_amount > 0 then
    raise exception 'Hóa đơn đã có tiền thanh toán. Không thể hoàn tác chốt nợ.';
  end if;
  if invoice_row.payment_status <> 'unpaid' or invoice_row.is_settlement is true then
    raise exception 'Chỉ được hoàn tác hóa đơn chưa thu, chưa gộp hoặc hủy.';
  end if;
  select * into room_row from public.rooms where id = invoice_row.room_id for update;
  if not found or room_row.status <> 'occupied' or not exists (
    select 1 from public.contracts c
    where c.room_id = invoice_row.room_id and c.tenant_id = invoice_row.tenant_id
      and c.status = 'active' and c.created_at <= invoice_row.created_at
  ) then
    raise exception 'Phòng hoặc hợp đồng đã thay đổi. Không thể hoàn tác mốc điện nước.';
  end if;
  if exists (
    select 1 from public.invoices later
    where later.room_id = invoice_row.room_id
      and later.tenant_id = invoice_row.tenant_id
      and later.id <> invoice_row.id
      and later.payment_status not in ('cancelled', 'merged')
      and (coalesce(later.billing_reason, '') in ('first_month', 'monthly', 'room_cycle')
           or later.is_first_month is true)
      and (later.year, later.month) > (invoice_row.year, invoice_row.month)
  ) then
    raise exception 'Đã có hóa đơn kỳ sau. Không thể hoàn tác mốc điện nước.';
  end if;

  select * into room_row from public.rooms where id = invoice_row.room_id for update;
  if not found then raise exception 'Không tìm thấy phòng.'; end if;
  if room_row.electric_new is distinct from invoice_row.electric_new
     or room_row.water_new is distinct from invoice_row.water_new then
    raise exception 'Mốc điện nước đã thay đổi. Cần điều chỉnh thủ công trước khi hoàn tác.';
  end if;

  perform set_config('app.invoice_debt_reopen', 'on', true);
  update public.invoices
  set debt_confirmed_at = null, debt_confirmed_by = null,
      note = concat_ws(E'\n', note, '[Hoàn tác chốt nợ] ' || actor_id::text || ' ' || now()::text)
  where id = p_invoice_id
  returning * into invoice_row;

  update public.rooms
  set electric_old = invoice_row.electric_old,
      electric_new = invoice_row.electric_old,
      water_old = invoice_row.water_old,
      water_new = invoice_row.water_old
  where id = invoice_row.room_id;

  return jsonb_build_object('invoice', to_jsonb(invoice_row), 'applied', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.tenant_email_check(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if coalesce(auth.role(),'')<>'service_role' and not exists(select 1 from users where id=auth.uid() and status='active') then
  raise exception 'Cần đăng nhập tài khoản hệ thống để kiểm tra email.';
 end if;
 return jsonb_build_object('allowed',not tenant_system_email_conflict(p_email),
  'reason',case when tenant_system_email_conflict(p_email) then 'Email này thuộc tài khoản hệ thống. Hãy dùng email riêng của người thuê.' else null end);
end $function$

CREATE OR REPLACE FUNCTION public.tenant_payment_fallback(p_user uuid, p_contract text, p_cycle uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts%rowtype; cy tenant_payment_cycles%rowtype; token uuid;
 m text:=p_data->>'meter'; n integer; old_n integer; failures integer; camera_error boolean:=p_data->'cameraError'='true'::jsonb;
begin
 c:=tenant_payment_scope(p_user,p_contract);
 perform pg_advisory_xact_lock(20261005,120000);
 select * into c from contracts where id=c.id for update;
 select * into cy from tenant_payment_cycles where id=p_cycle and contract_id=c.id for update;
 if not found or cy.invoice_id is not null then raise exception 'Kỳ này chưa mở ghi số hoặc đã có hóa đơn.';end if;
 if cy.revision<>coalesce(c.revision_no,1) then raise exception 'Hợp đồng đã thay đổi. Chủ nhà cần kiểm tra.';end if;
 if not exists(select 1 from rooms where id=c.room_id and status='occupied') then raise exception 'Phòng không còn đang thuê.';end if;
 if m is null or m not in ('electric','water') then raise exception 'Loại công tơ không hợp lệ.';end if;
 if p_action='ocr_failure' then
  if m='electric' then update tenant_payment_cycles set electric_ocr_failures=least(electric_ocr_failures+1,100) where id=cy.id;
  else update tenant_payment_cycles set water_ocr_failures=least(water_ocr_failures+1,100) where id=cy.id;end if;
  return jsonb_build_object('ok',true);
 end if;
 if p_action is distinct from 'manual' then raise exception 'Thao tác không hợp lệ.';end if;
 failures:=case when m='electric' then cy.electric_ocr_failures else cy.water_ocr_failures end;
 -- Camera availability is declared by the user device, not proof of a photograph.
 if failures<2 and not coalesce(camera_error,false) then raise exception 'Hãy chụp lại. Nhập thủ công được mở sau 2 lần OCR lỗi hoặc khi camera không mở được.';end if;
 if jsonb_typeof(p_data->'reading') is distinct from 'number' or (p_data->>'reading') !~ '^\d{1,8}$' then raise exception 'Chỉ số phải là số nguyên.';end if;
 n:=(p_data->>'reading')::integer;old_n:=case when m='electric' then cy.electric_old else cy.water_old end;
 if n<old_n or n>99999999 or n-old_n>cy.elapsed_days*(case when m='electric' then 40 else 2 end) then raise exception 'Chỉ số thấp hơn số cũ hoặc tăng bất thường.';end if;
 insert into tenant_meter_manual_entries(cycle_id,user_id,meter,reading,reason)
 values(cy.id,p_user,m,n,case when coalesce(camera_error,false) then 'camera_unavailable' else 'ocr_failed' end) returning id into token;
 if m='electric' then update tenant_payment_cycles set electric_new=n,electric_source='manual' where id=cy.id;
 else update tenant_payment_cycles set water_new=n,water_source='manual' where id=cy.id;end if;
 return jsonb_build_object('source','manual','confirmationToken',token);
end $function$

CREATE OR REPLACE FUNCTION public.tenant_payment_scope(p_user uuid, p_contract text)
 RETURNS contracts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts%rowtype;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Không có quyền truy cập.' using errcode='42501';end if;
 select ctr.* into c from contracts ctr join tenants t on t.id=ctr.tenant_id
 join tenant_web_accounts a on a.tenant_id=t.id
 where ctr.id=p_contract and ctr.status='active' and t.is_active and a.status='active' and a.auth_user_id=p_user;
 if not found then raise exception 'Hợp đồng hoặc tài khoản không còn hoạt động.';end if;
 return c;
end $function$

CREATE OR REPLACE FUNCTION public.tenant_payment_state(p_user uuid, p_contract text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts%rowtype; current_id uuid; cy tenant_payment_cycles%rowtype; history jsonb; bills jsonb; bank jsonb; notices jsonb;
begin
 c:=tenant_payment_scope(p_user,p_contract); current_id:=ensure_tenant_payment_cycle(p_user,p_contract);
 select * into cy from tenant_payment_cycles where contract_id=c.id and invoice_id is null order by period limit 1;
 if cy.id is null then select * into cy from tenant_payment_cycles where id=current_id;end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.year desc,q.month desc,q.created_at desc),'[]') into bills from (
 select i.* from invoices i where i.room_id=c.room_id and i.tenant_id=c.tenant_id
  and (i.web_contract_id=c.id or (i.web_contract_id is null and i.created_at>=c.created_at))
  and i.payment_status not in ('cancelled','merged') order by i.year desc,i.month desc,i.created_at desc limit 60) q;
 -- Expose invoice business fields only; internal payment notes/actor IDs stay private.
 bills:=(select coalesce(jsonb_agg(value-'payment_records'-'note'-'damage_note'-'debt_confirmed_by'), '[]') from jsonb_array_elements(bills));
 select jsonb_build_object('name',bank_id,'account',account_no,'owner',case when upper(account_name)='DO KIM NGAN' then 'Đỗ Kim Ngân' else account_name end) into bank from app_settings limit 1;
 select coalesce(jsonb_agg(jsonb_build_object('invoiceId',s.invoice_id,'status',s.status,'amount',s.amount)),'[]') into notices
  from sepay_server_transactions s where s.invoice_id in (select value->>'id' from jsonb_array_elements(bills)) and s.status in ('partial','over','ambiguous');
 return jsonb_build_object('cycle',case when cy.id is null then null else to_jsonb(cy) end,'invoices',bills,'bank',bank,'notices',notices,
 'blockedReason',case when coalesce(c.billing_cycle,1)<>1 then 'Hợp đồng có chu kỳ thu tiền nhiều tháng. Chủ nhà cần lập hóa đơn theo chu kỳ đã thỏa thuận.'
 when c.transfer_history is not null and nullif(c.transfer_history->>'history_billed_in_invoice_id','') is null then 'Có kỳ chuyển phòng chưa quyết toán. Chủ nhà cần kiểm tra trước khi mở ghi số.'
 when cy.invoice_id is not null and exists(select 1 from invoices where id=cy.invoice_id and payment_status in ('cancelled','merged')) then 'Hóa đơn kỳ này đã được hủy hoặc gộp. Chủ nhà cần kiểm tra trước khi lập lại.'
 when cy.id is null and date_trunc('month',c.move_in_date)=date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh') and not coalesce(c.is_migration,false) then 'Hóa đơn tháng đầu và tiền cọc cần được lập theo bàn giao trong phần mềm. Ghi số điện nước hằng tháng bắt đầu từ kỳ tiếp theo.'
 else null end,
 'nextDate',case when (now() at time zone 'Asia/Ho_Chi_Minh')::date < date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date+coalesce(c.invoice_day,5)-1
  then date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date+coalesce(c.invoice_day,5)-1 else (date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')+interval '1 month')::date+coalesce(c.invoice_day,5)-1 end);
end $function$

CREATE OR REPLACE FUNCTION public.tenant_payment_write(p_user uuid, p_contract text, p_cycle uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contracts%rowtype; cy tenant_payment_cycles%rowtype; ph tenant_meter_photos%rowtype; token uuid;
 n int; old_n int; v_meter text:=p_data->>'meter'; src text; inv invoices%rowtype; total bigint; today date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
 c:=tenant_payment_scope(p_user,p_contract);
 perform pg_advisory_xact_lock(20261005,120000);
 select * into c from contracts where id=c.id for update;
 select * into cy from tenant_payment_cycles where id=p_cycle and contract_id=c.id for update;
 if not found then raise exception 'Kỳ thanh toán không thuộc tài khoản này.';end if;
 if cy.invoice_id is not null then return jsonb_build_object('invoiceId',cy.invoice_id);end if;
 if cy.revision<>coalesce(c.revision_no,1) then raise exception 'Hợp đồng đã thay đổi. Chủ nhà cần kiểm tra kỳ thanh toán.';end if;
 if not exists(select 1 from rooms where id=c.room_id and status='occupied') then raise exception 'Phòng không còn trong trạng thái đang thuê.';end if;
 if p_action in ('photo','confirm') then
  if v_meter not in ('electric','water') or v_meter is null then raise exception 'Loại công tơ không hợp lệ.';end if;
  n:=(p_data->>'reading')::integer;old_n:=case when v_meter='electric' then cy.electric_old else cy.water_old end;
  if n is null or n<old_n or n>99999999 or n-old_n>cy.elapsed_days*(case when v_meter='electric' then 40 else 2 end) then raise exception 'Chỉ số tăng bất thường hoặc thấp hơn số cũ. Cần chụp lại và kiểm tra.';end if;
  if p_action='photo' then
   insert into tenant_meter_photos(cycle_id,user_id,meter,reading,image) values(cy.id,p_user,v_meter,n,p_data->>'image') returning tenant_meter_photos.token into token;
   return jsonb_build_object('reviewToken',token);
  end if;
  select * into ph from tenant_meter_photos where tenant_meter_photos.token=(p_data->>'reviewToken')::uuid and cycle_id=cy.id and user_id=p_user and tenant_meter_photos.meter=v_meter for update;
  if not found or ph.expires_at<now() then raise exception 'Ảnh đã hết hạn hoặc chưa được kiểm tra. Hãy chụp lại.';end if;
  src:=case when n=ph.reading then 'ai-ocr' else 'manual' end;
  update tenant_meter_photos set confirmed_at=now(),corrected_reading=n,source=src where tenant_meter_photos.token=ph.token;
  if v_meter='electric' then update tenant_payment_cycles set electric_new=n,electric_source=src where id=cy.id;
  else update tenant_payment_cycles set water_new=n,water_source=src where id=cy.id;end if;
  return jsonb_build_object('source',src,'confirmationToken',ph.token);
 end if;
 if p_action<>'create' then raise exception 'Thao tác không hợp lệ.';end if;
 if cy.electric_new is null or cy.water_new is null then raise exception 'Cần xác nhận cả điện và nước trước khi lập hóa đơn.';end if;
 -- Recheck against Electron invoices and reading changes under the same lock.
 select * into inv from invoices i where i.room_id=c.room_id and i.tenant_id=c.tenant_id
 and (i.web_contract_id=c.id or (i.web_contract_id is null and i.created_at>=c.created_at))
 and i.month=extract(month from cy.period) and i.year=extract(year from cy.period)
 and i.payment_status not in ('cancelled','merged') and (i.billing_reason in ('monthly','first_month','room_cycle') or i.is_first_month) order by i.created_at desc limit 1;
 if inv.id is not null then update tenant_payment_cycles set invoice_id=inv.id where id=cy.id;return jsonb_build_object('invoiceId',inv.id);end if;
 if exists(select 1 from invoices i where i.room_id=c.room_id and i.tenant_id=c.tenant_id
  and (i.web_contract_id=c.id or (i.web_contract_id is null and i.created_at>=c.created_at))
  and i.payment_status not in ('cancelled','merged') and i.billing_reason='monthly'
  and coalesce(i.billing_period_end,i.invoice_date)>=cy.period_start) then raise exception 'Đã có hóa đơn với kỳ ghi số chồng lấn. Chủ nhà cần kiểm tra.';end if;
 select * into inv from invoices i where i.room_id=c.room_id and i.tenant_id=c.tenant_id
 and (i.web_contract_id=c.id or (i.web_contract_id is null and i.created_at>=c.created_at)) and i.payment_status not in ('cancelled','merged')
 and i.billing_reason in ('monthly','first_month','contract_end') and coalesce(i.billing_period_end,i.invoice_date)<cy.period
 order by coalesce(i.billing_period_end,i.invoice_date) desc,i.created_at desc limit 1;
 if coalesce(inv.electric_new,c.electric_init)<>cy.electric_old or coalesce(inv.water_new,c.water_init)<>cy.water_old then raise exception 'Chỉ số kỳ trước đã thay đổi. Chủ nhà cần kiểm tra trước khi lập hóa đơn.';end if;
 total:=cy.room_cost::bigint+cy.wifi_cost+cy.garbage_cost+(cy.electric_new-cy.electric_old)::bigint*cy.electric_price+(cy.water_new-cy.water_old)::bigint*cy.water_price;
 if total<0 or total>2147483647 then raise exception 'Tổng tiền vượt giới hạn hóa đơn.';end if;
 inv.id:='inv-web-'||replace(gen_random_uuid()::text,'-','');
 insert into invoices(id,room_id,tenant_id,web_contract_id,billing_reason,month,year,invoice_date,due_date,billing_period_start,billing_period_end,
 electric_old,electric_new,electric_usage,electric_cost,electric_price_snapshot,water_old,water_new,water_usage,water_cost,water_price_snapshot,
 room_cost,wifi_cost,garbage_cost,old_debt,total_amount,paid_amount,payment_status,payment_method,payment_records,is_first_month,is_settlement)
 values(inv.id,cy.room_id,cy.tenant_id,c.id,'monthly',extract(month from cy.period),extract(year from cy.period),today,today+5,cy.period_start,cy.period_end,
 cy.electric_old,cy.electric_new,cy.electric_new-cy.electric_old,(cy.electric_new-cy.electric_old)*cy.electric_price,cy.electric_price,
 cy.water_old,cy.water_new,cy.water_new-cy.water_old,(cy.water_new-cy.water_old)*cy.water_price,cy.water_price,
 cy.room_cost,cy.wifi_cost,cy.garbage_cost,0,total,0,case when total=0 then 'paid' else 'unpaid' end,'transfer','[]',false,false);
 update tenant_payment_cycles set invoice_id=inv.id where id=cy.id;
 -- Existing invoice/payment ledger is reused. Tenant cannot mark it paid.
 return jsonb_build_object('invoiceId',inv.id);
end $function$

CREATE OR REPLACE FUNCTION public.transfer_between_wallets(p_source text, p_amount bigint, p_request_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare position jsonb; existing public.wallet_transfer_requests%rowtype; target text; note text;
begin
  if not exists(select 1 from public.users u where u.id = auth.uid() and u.status = 'active' and u.role = 'admin') then
    raise exception 'Chỉ quản trị viên được ghi chuyển giữa các ví.' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(20261005, 120000);
  if p_source is null or p_source not in ('cash', 'transfer') or p_amount is null or p_amount <= 0 or nullif(btrim(p_request_id), '') is null then
    raise exception 'Thông tin chuyển ví không hợp lệ.';
  end if;
  select * into existing from public.wallet_transfer_requests where id = p_request_id;
  if found then
    if existing.source = p_source and existing.amount = p_amount and existing.created_by = auth.uid() then return; end if;
    raise exception 'Mã chuyển ví đã được sử dụng.';
  end if;
  position := public.wallet_position();
  if (position->>'unknown_count')::bigint > 0 or (position->>'cash')::bigint < 0 or (position->>'bank')::bigint < 0 then
    raise exception 'Phải đối soát số dư cũ trước khi chuyển giữa các ví.';
  end if;
  if p_amount > (position->>(case when p_source = 'cash' then 'cash' else 'bank' end))::bigint then
    raise exception 'Ví nguồn không đủ tiền.';
  end if;
  target := case when p_source = 'cash' then 'transfer' else 'cash' end;
  note := 'Chuyển giữa các ví: ' || case when p_source = 'cash' then 'Tiền mặt → Ngân hàng' else 'Ngân hàng → Tiền mặt' end;
  insert into public.wallet_transfer_requests(id, source, amount, created_by) values(p_request_id, p_source, p_amount, auth.uid());
  insert into public.cash_transactions(id, type, category, transaction_date, amount, payment_method, note, created_at, updated_at)
  values ('wallet-out-' || p_request_id, 'expense', 'wallet_transfer', now(), p_amount, p_source, note, now(), now()),
    ('wallet-in-' || p_request_id, 'income', 'wallet_transfer', now(), p_amount, target, note, now(), now());
end;
$function$

CREATE OR REPLACE FUNCTION public.wallet_check_result()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare position jsonb;
begin
  position := public.wallet_position();
  if (position->>'unknown_count')::bigint > 0 then
    raise exception 'Có giao dịch chưa xác định ví. Phải đối soát trước khi chi.';
  end if;
  if (position->>'cash')::bigint < 0 or (position->>'bank')::bigint < 0 then
    raise exception 'Ví đã chọn không đủ tiền. Phải chuyển giữa các ví trước khi chi; không cộng gộp hoặc tự đổi ví.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.wallet_position()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  checkpoint public.wallet_reconciliations%rowtype;
  settings public.app_settings%rowtype;
  basis public.wallet_accounting_basis%rowtype;
  bank_amount bigint;
  cash_amount bigint;
  unknown_amount bigint;
  unknown_count bigint;
begin
  select * into checkpoint from public.wallet_reconciliations limit 1;
  select * into settings from public.app_settings limit 1;
  select * into basis from public.wallet_accounting_basis limit 1;
  select coalesce(sum(e.delta) filter (where e.method = 'transfer'), 0),
    coalesce(sum(e.delta) filter (where e.method = 'cash'), 0),
    coalesce(sum(e.delta) filter (where e.method = 'unknown'), 0),
    count(*) filter (where e.method = 'unknown')
  into bank_amount, cash_amount, unknown_amount, unknown_count
  from public.wallet_ledger_entries() e
  where case when basis.id is not null then e.entry_date >= basis.starts_on::text
    when checkpoint.id is not null then not (e.entry_id = any(checkpoint.entry_ids))
    else settings.opening_balance_date is null or e.entry_date >= settings.opening_balance_date::text end;
  bank_amount := bank_amount + case when basis.id is not null then 0 else coalesce(checkpoint.bank_balance, settings.opening_balance_bank, 0) end;
  cash_amount := cash_amount + case when basis.id is not null then 0 else coalesce(checkpoint.cash_balance, settings.opening_balance_cash, 0) end;
  return jsonb_build_object('bank', bank_amount, 'cash', cash_amount, 'unknown', unknown_amount,
    'unknown_count', unknown_count, 'total', bank_amount + cash_amount + unknown_amount);
end;
$function$

CREATE OR REPLACE FUNCTION public.webmobile_auth_rate(p_ip text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare bucket text := 'auth:'||p_ip||':'||to_char(now(),'YYYYMMDDHH24MI'); hits integer;
begin
  delete from webmobile_auth_sessions where expires_at<now();
  insert into webmobile_demo_limits(key,count,expires_at) values(bucket,1,now()+interval '10 minutes')
  on conflict(key) do update set count=webmobile_demo_limits.count+1 returning count into hits;
  return hits<=10;
end $function$

CREATE OR REPLACE FUNCTION public.webmobile_demo_claim(p_id uuid, p_lease uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result jsonb;
begin
  delete from webmobile_demo_sessions where updated_at < now() - interval '24 hours' and (locked_until is null or locked_until < now());
  insert into webmobile_demo_sessions(id) values(p_id) on conflict do nothing;
  update webmobile_demo_sessions set lease=p_lease, locked_until=now()+interval '60 seconds', updated_at=now()
    where id=p_id and (locked_until is null or locked_until < now()) returning state into result;
  if not found then return jsonb_build_object('busy', true); end if;
  return jsonb_build_object('busy', false, 'state', result);
end $function$

CREATE OR REPLACE FUNCTION public.webmobile_demo_quota(p_ip text, p_session uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare day_key text := to_char(now() at time zone 'Asia/Ho_Chi_Minh', 'YYYY-MM-DD');
bucket text; current_count integer; max_count integer;
begin
  -- Serializes quota updates for the same day, independently of OCR requests.
  perform pg_advisory_xact_lock(hashtext('webmobile-demo-quota-' || day_key));
  delete from webmobile_demo_limits where expires_at < now();
  for bucket, max_count in select * from (values
    ('global:' || day_key, 200), ('ip:' || day_key || ':' || p_ip, 120), ('session:' || day_key || ':' || p_session::text, 20)
  ) as limits(key, maximum) loop
    select count into current_count from webmobile_demo_limits where key=bucket;
    if coalesce(current_count, 0) >= max_count then return false; end if;
  end loop;
  for bucket in select * from (values ('global:' || day_key), ('ip:' || day_key || ':' || p_ip), ('session:' || day_key || ':' || p_session::text)) as limits(key) loop
    insert into webmobile_demo_limits(key, count, expires_at) values(bucket, 1, now()+interval '48 hours')
      on conflict(key) do update set count=webmobile_demo_limits.count+1;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.webmobile_enroll_tenant(p_user_id uuid, p_tenant_id text, p_email text, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists(select 1 from public.users where id=p_actor and role='admin' and status='active') then raise exception 'Admin required'; end if;
  if not exists(select 1 from public.tenants where id=p_tenant_id and is_active and lower(btrim(email))=p_email) then raise exception 'Tenant/email mismatch'; end if;
  if not exists(select 1 from auth.users where id=p_user_id and raw_app_meta_data->>'portal_role'='webmobile_tenant') then raise exception 'Invalid portal identity'; end if;
  update auth.users set role='anon' where id=p_user_id;
  delete from public.users where id=p_user_id;
  insert into public.tenant_web_accounts(tenant_id,auth_user_id,email,created_by) values(p_tenant_id,p_user_id,p_email,p_actor);
end $function$

CREATE OR REPLACE FUNCTION public.webmobile_prepare_tenant_auth(p_user uuid, p_tenant text, p_email text, p_actor uuid, p_confirmation uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c contract_confirmations;
begin
 if p_user is null or p_user='00000000-0000-0000-0000-000000000000'::uuid then raise exception 'Invalid portal identity'; end if;
 if not exists(select 1 from users where id=p_actor and role='admin' and status='active') then raise exception 'Admin required'; end if;
 if not exists(select 1 from tenants where id=p_tenant and is_active and lower(btrim(email))=p_email) then raise exception 'Tenant/email mismatch'; end if;
 if p_confirmation is not null then
  select * into c from contract_confirmations where id=p_confirmation;
  if c.id is null or c.status<>'confirmed' or c.account_ready_at is not null or c.expires_at<=now()
   or c.account_locked_until is null or c.account_locked_until<=now() or c.account_lease is null or c.account_user_id is distinct from p_user
   or c.recipient_email is distinct from p_email or c.created_by is distinct from p_actor
   or (c.snapshot#>>'{tenant,id}') is distinct from p_tenant
   or not exists(select 1 from contracts where id=c.contract_id and tenant_id=p_tenant and status='active') then
   raise exception 'Phiên cấp tài khoản đã thay đổi.';
  end if;
 end if;
 perform pg_advisory_xact_lock(hashtext('tenant-email:'||p_email));
 if tenant_system_email_conflict(p_email) then raise exception 'Email này thuộc tài khoản hệ thống. Hãy dùng email riêng của người thuê.'; end if;
 if exists(select 1 from auth.users where id=p_user) or exists(select 1 from tenant_web_accounts where tenant_id=p_tenant or email=p_email) then raise exception 'Khách này đã có tài khoản website.'; end if;
 delete from tenant_auth_provisions where expires_at<=now();
 insert into tenant_auth_provisions(user_id,tenant_id,email,confirmation_id,expires_at)
 values(p_user,p_tenant,p_email,p_confirmation,now()+interval '60 seconds')
 on conflict(user_id) do update set expires_at=excluded.expires_at
 where tenant_auth_provisions.tenant_id=excluded.tenant_id and tenant_auth_provisions.email=excluded.email
  and tenant_auth_provisions.confirmation_id is not distinct from excluded.confirmation_id;
 if not found then raise exception 'Portal reservation mismatch'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.webmobile_revoke_tenant(p_tenant_id text, p_status text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare portal_id uuid;
begin
  if p_status is not null and p_status not in ('lock','unlock') then raise exception 'Invalid status'; end if;
  update tenant_web_accounts set session_version=session_version+1,
    status=case when p_status='lock' then 'locked' when p_status='unlock' then case when activated_at is null then 'pending' else 'active' end else status end,
    updated_at=now()
  where tenant_id=p_tenant_id returning auth_user_id into portal_id;
  if portal_id is null then raise exception 'Account missing'; end if;
  delete from webmobile_auth_sessions where user_id=portal_id;
end $function$

CREATE OR REPLACE FUNCTION public.webmobile_save_tenant_session(p_id uuid, p_user uuid, p_version integer, p_access text, p_refresh text, p_expiry timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare current_version integer;
begin
  select session_version into current_version from tenant_web_accounts where auth_user_id=p_user and status<>'locked' for update;
  if current_version is null or current_version<>p_version then raise exception 'Session revoked'; end if;
  insert into webmobile_auth_sessions(id,user_id,account_version,access_token,refresh_token,token_expires_at)
  values(p_id,p_user,p_version,p_access,p_refresh,p_expiry);
  update tenant_web_accounts set status='active',activated_at=coalesce(activated_at,now()),last_login_at=now(),updated_at=now() where auth_user_id=p_user;
end $function$
